# pypdf refuses to decompress any single PDF stream past this size, as
# a guard against zip-bomb attacks (default 75MB). Legitimate academic
# PDFs with large embedded diagrams/scans can have individual streams
# that decompress past that default and trip the guard, raising
# LimitReachedError and aborting extraction for the whole file even
# though nothing is actually malicious. Uploads here are the user's
# own textbook PDFs, not untrusted attacker payloads, so raise the cap
# rather than fail closed — but only modestly (200MB, comfortably
# above the ~96MB a real page in this app's PDFs has needed so far).
# Streamlit Community Cloud gives the whole process ~1GB of RAM, so
# raising this to something like 1GB (an earlier version of this fix
# did) effectively disabled the guard and risked an OOM kill instead
# of a catchable Python exception — which shows up as a bare "Oh no."
# crash page with no traceback, much harder to diagnose than this.
#
# pypdf >=6.16 reads this from a Configuration object rather than the
# plain module-level constants used before (those still exist for
# backwards compatibility but are deprecated and slated for removal in
# 7.0), so set both to stay correct across the versions in the wild.
_PDF_STREAM_LIMIT_BYTES = 200_000_000
try:
    pypdf.overwrite_configuration(
        zlib_maximum_output_length=_PDF_STREAM_LIMIT_BYTES,
        array_based_stream_maximum_output_length=_PDF_STREAM_LIMIT_BYTES,
        image_maximum_buffer_size=_PDF_STREAM_LIMIT_BYTES,
    )
except AttributeError:
    pass
import pypdf.filters as _pypdf_filters  # noqa: E402

_pypdf_filters.ZLIB_MAX_OUTPUT_LENGTH = _PDF_STREAM_LIMIT_BYTES


