_LATEX_FRAC_RE = re.compile(r"\\frac\{([^{}]*)\}\{([^{}]*)\}")
_LATEX_NTH_SQRT_RE = re.compile(r"\\sqrt\[([^\[\]]*)\]\{([^{}]*)\}")
_LATEX_SQRT_RE = re.compile(r"\\sqrt\{([^{}]*)\}")
_LATEX_TEXT_RE = re.compile(r"\\text\{([^{}]*)\}")
_LATEX_MATHBB_RE = re.compile(r"\\mathbb\{([A-Za-z])\}")
_LATEX_VEC_RE = re.compile(r"\\vec\{([^{}]*)\}")
_LATEX_HAT_RE = re.compile(r"\\hat\{([^{}]*)\}")
_LATEX_MATHRING_RE = re.compile(r"\\mathring\{([^{}]*)\}")
