    (_cmd(r"\\rightleftharpoons"), "⇌"),
    (_cmd(r"\\leftrightharpoons"), "⇋"),
    (_cmd(r"\\rightharpoonup"), "⇀"),
    (_cmd(r"\\leftrightarrow"), "↔"),
    (_cmd(r"\\rightarrow"), "→"),
    (_cmd(r"\\leftarrow"), "←"),
    (_cmd(r"\\to"), "→"),
    (_cmd(r"\\uparrow"), "↑"),
    (_cmd(r"\\downarrow"), "↓"),
    (_cmd(r"\\log"), "log"),
    (_cmd(r"\\ln"), "ln"),
    (_cmd(r"\\lim"), "lim"),
    (_cmd(r"\\sin"), "sin"),
    (_cmd(r"\\cos"), "cos"),
    (_cmd(r"\\tan"), "tan"),
