# XML 1.0 (the format python-docx/lxml write) forbids most C0/C1
# control characters and lone UTF-16 surrogates outright — lxml raises
# a bare "ValueError: All strings must be XML compatible..." (no
# useful traceback context) the moment one reaches Element.text, which
# is exactly the crash this strips at the source instead of chasing
# every add_run() call site individually. \t, \n and \r stay allowed
# since XML permits them.
_ILLEGAL_XML_CHARS_RE = re.compile(
    "[\x00-\x08\x0b\x0c\x0e-\x1f\x7f-\x84\x86-\x9f"
    "\ud800-\udfff﷐-﷯￾￿]"
)


def strip_illegal_xml_chars(value):
    return _ILLEGAL_XML_CHARS_RE.sub("", str(value or ""))


def sanitize_math_text(value):
    if value is None:
        return ""

    text = strip_illegal_xml_chars(value)

    # Multi-argument LaTeX macros are resolved first, since each one
    # consumes its own {...} braces before the generic command
    # stripper runs (otherwise stray braces would be left behind).
    text = re.sub(r"\{\}", "", text)

    for _ in range(3):
        text = _LATEX_FRAC_RE.sub(r"(\1)/(\2)", text)
        text = _LATEX_TEXT_RE.sub(r"\1", text)

    text = _LATEX_NTH_SQRT_RE.sub(r"√[\1](\2)", text)
    text = _LATEX_SQRT_RE.sub(r"√(\1)", text)

    # Unicode cube/fourth-root characters, if the model emits them
    # directly, are normalized into the same "√[n](...)" shape the
    # DOCX radical-field renderer looks for.
    text = text.replace("∛", "√[3]")
    text = text.replace("∜", "√[4]")

    text = _LATEX_MATHBB_RE.sub(
        lambda m: _MATHBB_LOOKUP.get(m.group(1).upper(), m.group(1)),
        text,
    )

    text = _LATEX_VEC_RE.sub(
        lambda m: m.group(1) + _COMBINING_VECTOR_ARROW, text
    )
    text = _LATEX_HAT_RE.sub(
        lambda m: m.group(1) + _COMBINING_CIRCUMFLEX, text
    )
    text = _LATEX_MATHRING_RE.sub(
        lambda m: m.group(1) + _COMBINING_RING_ABOVE, text
    )
    text = _LATEX_DDOT_RE.sub(
        lambda m: m.group(1) + _COMBINING_DIAERESIS, text
    )
    text = _LATEX_DOT_RE.sub(
        lambda m: m.group(1) + _COMBINING_DOT_ABOVE, text
    )

    text = _LATEX_XRIGHTARROW_BRACKET_RE.sub(r"→ (\2, \1)", text)
    text = _LATEX_XRIGHTARROW_RE.sub(r"→ (\1)", text)
    text = _LATEX_XLEFTARROW_BRACKET_RE.sub(r"← (\2, \1)", text)
    text = _LATEX_XLEFTARROW_RE.sub(r"← (\1)", text)

    # "^\circ" / "^{\circ}" and "^\prime" / "^{\prime}" are a raised
    # command, not a raised letter — collapse straight to the symbol
    # rather than leaving a dangling "^" for the superscript engine.
    text = _LATEX_CIRC_SUPERSCRIPT_RE.sub("°", text)
    text = _LATEX_PRIME_SUPERSCRIPT_RE.sub("′", text)

    for pattern, replacement in _LATEX_REPLACEMENTS:
        text = re.sub(pattern, replacement, text)

    text = re.sub(r"\\[A-Za-z]+", "", text)

    return re.sub(r"[ \t]{2,}", " ", text).strip()


def contains_unwanted_script(value):
    if not value:
        return False

    allowed = [
        (0x0000, 0x024F),
        (0x0300, 0x036F),  # combining diacritical marks (vec/hat/dot)
        (0x0370, 0x03FF),
        (0x1D00, 0x1D7F),
        (0x2000, 0x206F),
        (0x2070, 0x209F),
        (0x20D0, 0x20FF),  # combining marks for symbols (vector arrow)
        (0x2100, 0x214F),
        (0x2190, 0x21FF),
        (0x2200, 0x22FF),
        (0x2300, 0x23FF),
        (0x25A0, 0x25FF),
        (0x2600, 0x26FF),
        (0x27C0, 0x27EF),
        (0x27F0, 0x27FF),  # supplemental arrows-A (long reaction arrows)
        (0x2980, 0x29FF),
        (0x2A00, 0x2AFF),
    ]

    for char in str(value):
        if char in "\n\r\t" or char.isspace() or char.isdigit():
            continue

        point = ord(char)

        if not any(start <= point <= end for start, end in allowed):
            return True

    return False


def contains_generic_question(value):
    text = str(value or "").lower()

    return any(
        re.search(pattern, text)
        for pattern in GENERIC_PATTERNS
    )


def normalize_text(value):
    return re.sub(
        r"\s+",
        " ",
        str(value or "").lower(),
    ).strip()


def token_set(value):
    return set(
        re.findall(
            r"[a-z0-9]+",
            normalize_text(str(value or "").replace("_", " ")),
        )
    )


def jaccard_similarity(a, b):
    set_a = token_set(a)
    set_b = token_set(b)

    if not set_a or not set_b:
        return 0.0

    return len(set_a & set_b) / len(set_a | set_b)


def texts_match(a, b, ratio_threshold, jaccard_threshold):
    ratio = SequenceMatcher(
        None,
        normalize_text(a),
        normalize_text(b),
    ).ratio()

    jaccard = jaccard_similarity(a, b)

    return (ratio >= ratio_threshold) or (jaccard >= jaccard_threshold)


def slugify_concept(value):
    """
    Fallback canonical tag builder, used only when the model omits
    concept_id. Keeps concept-level dedup working even against a
    provider/model that doesn't perfectly follow the JSON schema.
    """

    text = normalize_text(value)
    text = re.sub(r"[^a-z0-9]+", "_", text).strip("_")

    return "_".join(text.split("_")[:6])


def is_duplicate_question(
    question,
    previous_questions,
):
    return any(
        texts_match(
            question,
            item,
            QUESTION_MATCH_RATIO,
            QUESTION_MATCH_JACCARD,
        )
        for item in previous_questions
    )


def is_duplicate_concept(
    concept_id,
    concept_text,
    previous_concepts,
):
    """
    previous_concepts is a list of {"id": concept_id, "text":
    concept_tested} dicts accumulated across the WHOLE run. A match on
    either the canonical tag or the free-text description is treated
    as the same underlying fact, even when the question itself is
    worded completely differently.
    """

    for item in previous_concepts:
        if concept_id and item.get("id") and texts_match(
            concept_id,
            item["id"],
            CONCEPT_TAG_MATCH_RATIO,
            CONCEPT_TAG_MATCH_JACCARD,
        ):
            return True

        if concept_text and item.get("text") and texts_match(
            concept_text,
            item["text"],
            CONCEPT_TEXT_MATCH_RATIO,
            CONCEPT_TEXT_MATCH_JACCARD,
        ):
            return True

    return False


def explanation_conflicts_with_key(explanation, key, options):
    """
    Detects the case where the model's explanation leaks its own
    chain-of-thought and ends up arguing for a different option than
    the one it actually stored as the answer key. Returns True when a
    conflict is detected — the question should be rejected.
    """

    text = str(explanation or "")

    if any(
        re.search(pattern, text, re.IGNORECASE)
        for pattern in HEDGING_PATTERNS
    ):
        return True

    claimed_numbers = set()

    for match in _EXPLANATION_OPTION_CLAIM_RE.finditer(text):
        for group in match.groups():
            if group:
                claimed_numbers.add(group)

    if claimed_numbers and str(key) not in claimed_numbers:
        return True

    return False


# ---------------------------------------------------------------------------
# DOCX MATH RENDERING
# ---------------------------------------------------------------------------
MATH_TOKEN_RE = re.compile(
    r"\^\{([^}]*)\}|_\{([^}]*)\}|\^([A-Za-z0-9+\-])|_([A-Za-z0-9+\-])"
)

# A "term" on either side of a fraction slash: a balanced single-level
# parenthesized group (this is what \frac{X}{Y} becomes after
# sanitize_math_text, e.g. "(3+4)/(5)"), a plain number, or a short
# algebraic token such as "a", "dy", "R2" (covers "a/b", "dy/dx",
# "GM/R" style fractions, not just bare numeric ones).
_FRACTION_TERM = (
    r"(?:\([^()]{1,80}\)"
    r"|-?\d+(?:\.\d+)?"
    r"|[A-Za-zΑ-Ωα-ω][A-Za-zΑ-Ωα-ω0-9]{0,8})"
)

FRACTION_RE = re.compile(
    rf"(?<![\w/])({_FRACTION_TERM})\s*/\s*({_FRACTION_TERM})(?![\w/])"
)

# Ordinary English word pairs that happen to contain a "/" and must
# never be treated as a fraction (and/or, his/her, etc). Deliberately
# excludes single letters (a, i, ...) since those are extremely
# common algebraic variable names — "a/b" must still become a real
# fraction field, not fall back to plain text.
FRACTION_STOPWORDS = {
    "and", "or", "he", "she", "his", "her", "him", "on", "off",
    "yes", "no", "an", "the", "you", "we", "it",
}

# A radical is "√" (or "√[n]" for an nth root) followed by either a
# balanced parenthesized radicand or a short bare token, e.g.
# "√(9+16+16)", "√41", "√[3](8)".
_RADICAL_START_RE = re.compile(r"√(?:\[(?P<index>[^\[\]]*)\])?")
_RADICAL_SIMPLE_TOKEN_RE = re.compile(r"[A-Za-zΑ-Ωα-ω0-9.]+")


def _find_balanced_parens(text, open_index):
    """
    text[open_index] must be '('. Returns the index just past the
    matching ')' (handling one or more levels of nesting), or None if
    unbalanced.
    """

    depth = 0

    for index in range(open_index, len(text)):
        if text[index] == "(":
            depth += 1
        elif text[index] == ")":
            depth -= 1

            if depth == 0:
                return index + 1

    return None


def find_next_radical(text, start):
    """
    Finds the next "√" (optionally "√[index]") in text starting at
    `start`, along with its radicand. Returns
    (match_start, match_end, index_or_None, radicand) or None if
    there is no further radical in the text.
    """

    match = _RADICAL_START_RE.search(text, start)

    if match is None:
        return None

    index = match.group("index") or None
    cursor = match.end()

    if cursor < len(text) and text[cursor] == "(":
        close = _find_balanced_parens(text, cursor)

        if close is None:
            # Unbalanced — treat the radical sign itself as plain
            # text rather than risk mangling the rest of the string.
            return (match.start(), match.start() + 1, None, None)

        radicand = text[cursor + 1:close - 1]

        return (match.start(), close, index, radicand)

    token_match = _RADICAL_SIMPLE_TOKEN_RE.match(text, cursor)

    if token_match:
        return (
            match.start(),
            token_match.end(),
            index,
            token_match.group(0),
        )

    # A bare "√" with nothing usable after it — emit it as plain text
    # rather than dropping/crashing.
    return (match.start(), match.start() + 1, None, None)


def _field_safe(value):
    """
    Word's EQ field instruction syntax uses commas to separate
    arguments, so any value containing a comma cannot be safely
    embedded — fall back to plain (unformatted) text for that one
    fraction/radical instead of emitting a broken field.
    """

    return "," not in str(value)


def add_word_fraction_field(
    paragraph,
    numerator,
    denominator,
):
    run = paragraph.add_run()
    run_xml = run._r

    def field_char(field_type):
        element = OxmlElement("w:fldChar")
        element.set(qn("w:fldCharType"), field_type)

        if field_type == "begin":
            element.set(qn("w:dirty"), "true")

        run_xml.append(element)

    def instruction(value):
        element = OxmlElement("w:instrText")
        element.set(qn("xml:space"), "preserve")
        element.text = value
        run_xml.append(element)

    field_char("begin")
    instruction(f"EQ \\f({numerator},{denominator})")
    field_char("separate")

    text_element = OxmlElement("w:t")
    text_element.set(qn("xml:space"), "preserve")
    text_element.text = f"{numerator}/{denominator}"
    run_xml.append(text_element)

    field_char("end")


def add_word_radical_field(
    paragraph,
    radicand,
    index=None,
):
    run = paragraph.add_run()
    run_xml = run._r

    def field_char(field_type):
        element = OxmlElement("w:fldChar")
        element.set(qn("w:fldCharType"), field_type)

        if field_type == "begin":
            element.set(qn("w:dirty"), "true")

        run_xml.append(element)

    def instruction(value):
        element = OxmlElement("w:instrText")
        element.set(qn("xml:space"), "preserve")
        element.text = value
        run_xml.append(element)

    field_char("begin")

    if index:
        instruction(f"EQ \\r({index},{radicand})")
    else:
        instruction(f"EQ \\r({radicand})")

    field_char("separate")

    text_element = OxmlElement("w:t")
    text_element.set(qn("xml:space"), "preserve")
    text_element.text = (
        f"{index}√({radicand})" if index else f"√({radicand})"
    )
    run_xml.append(text_element)

    field_char("end")


UNICODE_SUPERSCRIPT_MAP = {
    "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴",
    "5": "⁵", "6": "⁶", "7": "⁷", "8": "⁸", "9": "⁹",
    "+": "⁺", "-": "⁻", "(": "⁽", ")": "⁾", "n": "ⁿ",
}

UNICODE_SUBSCRIPT_MAP = {
    "0": "₀", "1": "₁", "2": "₂", "3": "₃", "4": "₄",
    "5": "₅", "6": "₆", "7": "₇", "8": "₈", "9": "₉",
    "+": "₊", "-": "₋", "(": "₍", ")": "₎",
}


def _map_chars(chars, mapping):
    return "".join(mapping.get(char, char) for char in chars)


def render_exponents_as_unicode(text):
    """
    Word's legacy EQ field syntax cannot nest true font-level
    superscript/subscript formatting inside a fraction or radical
    argument. Content that ends up INSIDE a field (e.g. the "3^{2}"
    in "√(3^{2}+4^{2}+4^{2})") is rendered with Unicode superscript/
    subscript characters instead ("3²") rather than left as a
    literal caret — this is exactly the fallback the JEE/NEET symbol
    reference itself lists for superscripts/subscripts.
    """

    def replace(match):
        if match.group(1) is not None:
            return _map_chars(match.group(1), UNICODE_SUPERSCRIPT_MAP)

        if match.group(2) is not None:
            return _map_chars(match.group(2), UNICODE_SUBSCRIPT_MAP)

        if match.group(3) is not None:
            return _map_chars(match.group(3), UNICODE_SUPERSCRIPT_MAP)

        if match.group(4) is not None:
            return _map_chars(match.group(4), UNICODE_SUBSCRIPT_MAP)

        return match.group(0)

    return MATH_TOKEN_RE.sub(replace, text)


def add_math_runs(paragraph, text):
    """
    Single left-to-right pass over sanitized text. At every position
    it looks for whichever of these starts earliest:
      - a radical (√41, √(9+16+16), √[3](8), ...)  -> a real Word
        EQ \\r field, with a bar that covers the whole radicand
      - a fraction (a/b, (a+b)/(c+d), ...)          -> a real Word
        EQ \\f field, stacked numerator/denominator
      - a ^{...}/_{...}/^X/_X token                 -> a true Word
        superscript/subscript run
    and processes that one, then continues from just past it. Plain
    text everywhere else becomes a normal run.

    Running fraction/radical detection and superscript/subscript
    detection as two SEPARATE passes (superscripts first) would
    fragment any radical or fraction that contains its own exponent
    — e.g. "√(3^{2}+4^{2}+4^{2})" — before the radical/fraction
    scanner ever sees it as one contiguous expression. Since Word's
    EQ field syntax can't nest true superscript formatting inside a
    fraction/radical argument anyway, any ^{...}/_{...} caught INSIDE
    a field is rendered with Unicode superscript/subscript characters
    (see render_exponents_as_unicode) instead of being lost.
    """

    text = sanitize_math_text(text)
    cursor = 0
    length = len(text)

    while cursor < length:
        frac_match = FRACTION_RE.search(text, cursor)
        radical = find_next_radical(text, cursor)
        token_match = MATH_TOKEN_RE.search(text, cursor)

        candidates = []

        if frac_match:
            candidates.append((frac_match.start(), "frac"))

        if radical:
            candidates.append((radical[0], "radical"))

        if token_match:
            candidates.append((token_match.start(), "token"))

        if not candidates:
            paragraph.add_run(text[cursor:])
            break

        next_start, kind = min(candidates, key=lambda item: item[0])

        if next_start > cursor:
            paragraph.add_run(text[cursor:next_start])

        if kind == "frac":
            numerator = frac_match.group(1)
            denominator = frac_match.group(2)

            # Strip one layer of wrapping parens for the field's own
            # value; any exponent/subscript inside becomes a Unicode
            # character since it can't be a true superscript here.
            num_value = numerator
            den_value = denominator

            if num_value.startswith("(") and num_value.endswith(")"):
                num_value = num_value[1:-1]

            if den_value.startswith("(") and den_value.endswith(")"):
                den_value = den_value[1:-1]

            num_value = render_exponents_as_unicode(num_value)
            den_value = render_exponents_as_unicode(den_value)

            is_stopword = (
                numerator.strip().lower() in FRACTION_STOPWORDS
                or denominator.strip().lower() in FRACTION_STOPWORDS
            )

            if is_stopword or not (
                _field_safe(num_value) and _field_safe(den_value)
            ):
                paragraph.add_run(
                    render_exponents_as_unicode(
                        text[frac_match.start():frac_match.end()]
                    )
                )
            else:
                add_word_fraction_field(paragraph, num_value, den_value)

            cursor = frac_match.end()

        elif kind == "radical":
            _, radical_end, index, radicand = radical

            if radicand is None:
                paragraph.add_run(text[next_start:radical_end])
            else:
                radicand_value = render_exponents_as_unicode(radicand)
                index_value = (
                    render_exponents_as_unicode(index) if index else None
                )

                if not _field_safe(radicand_value) or (
                    index_value is not None
                    and not _field_safe(index_value)
                ):
                    paragraph.add_run(
                        render_exponents_as_unicode(
                            text[next_start:radical_end]
                        )
                    )
                else:
                    add_word_radical_field(
                        paragraph, radicand_value, index_value
                    )

            cursor = radical_end

        else:  # kind == "token"
            match = token_match

            if match.group(1) is not None:
                run = paragraph.add_run(match.group(1))
                run.font.superscript = True

            elif match.group(2) is not None:
                run = paragraph.add_run(match.group(2))
                run.font.subscript = True

            elif match.group(3) is not None:
                run = paragraph.add_run(match.group(3))
                run.font.superscript = True

            elif match.group(4) is not None:
                run = paragraph.add_run(match.group(4))
                run.font.subscript = True

            cursor = match.end()


def set_light_border(cell):
    tc_pr = cell._tc.get_or_add_tcPr()
    borders = OxmlElement("w:tcBorders")

    for edge in ("top", "left", "bottom", "right"):
        element = OxmlElement(f"w:{edge}")
        element.set(qn("w:val"), "single")
        element.set(qn("w:sz"), "6")
        element.set(qn("w:space"), "0")
        element.set(qn("w:color"), "DDDDDD")
        borders.append(element)

    tc_pr.append(borders)


# ---------------------------------------------------------------------------
# PDF EXTRACTION
# ---------------------------------------------------------------------------
@st.cache_data(show_spinner=False)
def extract_pdf_pages(pdf_bytes):
    """
    Cached on pdf_bytes. This is the fix for the app feeling like it
    "keeps running" on every single interaction after upload —
    Streamlit reruns the ENTIRE script top-to-bottom on every widget
    interaction (checking a page's checkbox, adjusting a question
    count, typing a subtopic character), and the uploaded file's
    bytes are unchanged across all of those reruns. Without caching,
    every one of those interactions was re-running pypdf's full text
    extraction across every page from scratch — genuinely expensive
    for a 20+ page academic PDF — instead of being an instant
    UI-only update. With caching, only the FIRST call after a given
    PDF is uploaded does real work; every rerun after that is a
    cache hit.
    """

    reader = PdfReader(io.BytesIO(pdf_bytes))
    pages = []

    for index, page in enumerate(reader.pages):
        try:
            text = (page.extract_text() or "").strip()
        except Exception:
            # A single malformed/oversized stream on this page
            # shouldn't take down extraction for the whole PDF —
            # treat it like a page with no extractable text (the
            # existing has_text=False path already handles that,
            # e.g. via source-page image analysis).
            text = ""

        pages.append(
            {
                "page_number": index + 1,
                "text": text,
                "has_text": bool(text),
            }
        )

    return pages


@st.cache_data(show_spinner=False)
def render_all_pdf_page_previews(pdf_bytes, zoom=1.0):
    """
    Renders every page of the PDF to a PNG in ONE pass, returning
    {page_number: png_bytes_or_None}.

    This replaces an earlier per-page render function that opened
    and re-parsed the ENTIRE PDF from scratch on every single call
    (once per page) — for a 25-page file that meant parsing the
    whole document 25 separate times, plus @st.cache_data hashing
    the full multi-MB pdf_bytes argument 25 times too. That's the
    main reason uploading a larger or image-heavy PDF could feel
    like it hangs: opening one file once (here) is dramatically
    cheaper than opening it N times.
    """

    if fitz is None:
        return {}

    previews = {}
    pdf_document = None

    try:
        pdf_document = fitz.open(stream=pdf_bytes, filetype="pdf")
        matrix = fitz.Matrix(zoom, zoom)

        for page_index in range(len(pdf_document)):
            page_number = page_index + 1

            try:
                page = pdf_document.load_page(page_index)
                pixmap = page.get_pixmap(matrix=matrix, alpha=False)
                previews[page_number] = pixmap.tobytes("png")
            except Exception:
                previews[page_number] = None

    except Exception:
        return {}

    finally:
        if pdf_document is not None:
            pdf_document.close()

    return previews


# ---------------------------------------------------------------------------
# SOURCE FIGURE DETECTION
#
# Figures are found from the RENDERED PAGE, not from the PDF's image
# boxes: the page is rendered, every real text character is erased,
# full-width bands/rules are erased, and whatever ink is left is split
# into separate islands — one island per picture. This is what makes
# it robust to how textbook PDFs are actually built:
#   - several panels stored as ONE embedded image come out as separate
#     pictures, because the white space between them has no ink;
#   - an image whose white margin overlaps the paragraph above never
#     drags that paragraph in, because white margins carry no ink;
#   - page-decoration images (the coloured header/footer bands) and
#     text boxes/tables are recognised and ignored.
# Labels are real PDF text: each label goes to the ONE picture its
# leader line points at, or else the picture whose ink is nearest.
# ---------------------------------------------------------------------------
FIGURE_SEGMENT_ZOOM = 1.5          # pixels per PDF point used for detection
FIGURE_CELL_PT = 2.0               # detection grid resolution, in points
FIGURE_INK_THRESHOLD = 236         # grey level below which a pixel is ink
# Ink pieces closer than this belong to the same picture.
FIGURE_JOIN_GAP_PT = 4.0
# A picture smaller than this in either direction is a bullet, rule,
# icon or ornament, not a figure a question could be about.
MIN_FIGURE_SIZE_PT = 36
# Small fragments (an arrowhead, a detached cilium) within this
# distance of a picture belong to it; small drawings with no picture
# nearby (RBC / platelets / WBC sketches) are grouped with each other
# within this distance and become a picture if the group is big enough.
FIGURE_FRAGMENT_ATTACH_PT = 10
FIGURE_FRAGMENT_GROUP_PT = 24
FIGURE_LABEL_REACH_PT = 22
FIGURE_LABEL_MAX_CHARS = 40
FIGURE_LABEL_WORD_GAP_PT = 12
# A straight line with one end this close to a label is its pointer.
FIGURE_LEADER_TOUCH_PT = 8
# Running headers/footers (chapter title, page number, year) live in
# these top/bottom page bands and are never figure content.
FIGURE_HEADER_BAND = 0.10
FIGURE_FOOTER_BAND = 0.07
FIGURE_CAPTION_REACH_PT = 40
FIGURE_CAPTION_GROUP_REACH_PT = 320
FIGURE_PADDING_PT = 5
MAX_FIGURES_PER_PAGE = 10
# (max width in pixels, max file size in bytes) of each figure image
# written into the question bank.
FIGURE_SIZE_PRESETS = {
    "Small (≈60 KB)": (750, 60_000),
    "Medium (≈120 KB)": (1000, 120_000),
    "Large (≈200 KB)": (1400, 200_000),
}
DEFAULT_FIGURE_SIZE_PRESET = "Medium (≈120 KB)"
_FIGURE_CAPTION_RE = re.compile(r"^\s*(fig\.?|figure)\s*[0-9A-Za-z]", re.IGNORECASE)


def _rect_distance(first, second):
    dx = max(0.0, first.x0 - second.x1, second.x0 - first.x1)
    dy = max(0.0, first.y0 - second.y1, second.y0 - first.y1)
    return (dx * dx + dy * dy) ** 0.5


def _page_text_units(page):
    """
    Splits the page's real text into what matters for figures:
      words    — every word rectangle (erased before finding ink)
      labels   — short text near pictures ("Nucleus", "(a)"), one per
                 word group, with multi-line labels stacked together
      captions — "Figure N ..." blocks
      body     — paragraph blocks
    """

    try:
        blocks = [
            block
            for block in page.get_text("blocks")
            if block[6] == 0 and block[4].strip()
        ]
        words = page.get_text("words")
    except Exception:
        return [], [], [], []

    captions = []
    body = []
    short_blocks = set()

    for block in blocks:
        text = " ".join(block[4].split())

        if _FIGURE_CAPTION_RE.match(text):
            captions.append((fitz.Rect(block[:4]), text))
        elif len(text) <= FIGURE_LABEL_MAX_CHARS * 2 and block[4].strip().count("\n") <= 4:
            short_blocks.add(block[5])
        else:
            body.append(fitz.Rect(block[:4]))

    word_rects = [fitz.Rect(word[:4]) for word in words]
    lines = {}

    for x0, y0, x1, y1, text, block_number, line_number, _ in words:
        if block_number in short_blocks:
            lines.setdefault((block_number, line_number), []).append(
                (fitz.Rect(x0, y0, x1, y1), text)
            )

    segments = []

    for line_words in lines.values():
        line_words.sort(key=lambda item: item[0].x0)
        rect, texts = fitz.Rect(line_words[0][0]), [line_words[0][1]]

        for word_rect, text in line_words[1:]:
            if word_rect.x0 - rect.x1 > FIGURE_LABEL_WORD_GAP_PT:
                segments.append((rect, texts))
                rect, texts = fitz.Rect(word_rect), [text]
            else:
                rect.include_rect(word_rect)
                texts.append(text)

        segments.append((rect, texts))

    labels = []

    for rect, texts in sorted(segments, key=lambda item: (item[0].y0, item[0].x0)):
        for label in labels:
            gap = rect.y0 - label["rect"].y1
            overlaps_x = rect.x0 < label["rect"].x1 and rect.x1 > label["rect"].x0

            if -2 <= gap <= 3 and overlaps_x:
                label["rect"].include_rect(rect)
                label["text"] += " " + " ".join(texts)
                break
        else:
            labels.append(
                {"rect": fitz.Rect(rect), "text": " ".join(texts), "line_height": rect.height}
            )

    for label in labels:
        # "Macro-" + "phage" -> "Macrophage"
        label["text"] = re.sub(r"(\w)- (\w)", r"\1\2", label["text"]).strip()

    return word_rects, labels, captions, body


def _leader_lines(page, labels):
    """
    Straight single-stroke vector lines that start at a label: the
    pointer from a label to the part it names. Returned as
    (label_index, far_end_point). They are erased before finding ink
    so a pointer can never glue two pictures together.
    """

    leaders = []

    try:
        drawings = page.get_drawings()
    except Exception:
        return leaders

    for drawing in drawings:
        items = drawing.get("items") or []

        if drawing.get("fill") is not None or len(items) != 1 or items[0][0] != "l":
            continue

        start_point, end_point = fitz.Point(items[0][1]), fitz.Point(items[0][2])
        length = abs(end_point - start_point)

        if length < 3:
            continue

        best = None

        for index, label in enumerate(labels):
            rect = label["rect"]
            start_gap = _rect_distance(rect, fitz.Rect(start_point, start_point))
            end_gap = _rect_distance(rect, fitz.Rect(end_point, end_point))
            near_gap, far_gap = min(start_gap, end_gap), max(start_gap, end_gap)

            # One end touches the label, the other end reaches away
            # from it: that's a pointer from this label.
            if near_gap <= FIGURE_LEADER_TOUCH_PT and far_gap >= near_gap + 3:
                if best is None or near_gap < best[0]:
                    if start_gap <= end_gap:
                        best = (near_gap, index, end_point, start_point)
                    else:
                        best = (near_gap, index, start_point, end_point)

        if best is not None:
            leaders.append(best[1:])

    return leaders


def _connected_components(mask):
    """4-connected component labelling of a boolean grid (0 = background)."""

    height, width = mask.shape
    labels = np.zeros((height, width), dtype=np.int32)
    count = 0

    for row, col in np.argwhere(mask):
        if labels[row, col]:
            continue

        count += 1
        labels[row, col] = count
        stack = [(row, col)]

        while stack:
            r, c = stack.pop()

            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < height and 0 <= nc < width and mask[nr, nc] and not labels[nr, nc]:
                    labels[nr, nc] = count
                    stack.append((nr, nc))

    return labels, count


def _detect_page_figures(page):
    """
    Returns one dict per separate picture on the page:
      rect     — crop rectangle (picture + its own labels [+ caption])
      masks    — rectangles inside the crop that belong to something
                 else (other pictures, body text) and are blanked out
      labels   — the text of the labels that belong to this picture
      caption  — the "Figure N ..." caption that covers this picture
    """

    page_rect = page.rect
    header_limit = page_rect.y0 + FIGURE_HEADER_BAND * page_rect.height
    footer_limit = page_rect.y1 - FIGURE_FOOTER_BAND * page_rect.height

    def in_page_margin_band(rect):
        return rect.y1 <= header_limit or rect.y0 >= footer_limit

    word_rects, labels, captions, body = _page_text_units(page)
    labels = [label for label in labels if not in_page_margin_band(label["rect"])]
    leaders = _leader_lines(page, labels)

    zoom = FIGURE_SEGMENT_ZOOM
    pixmap = page.get_pixmap(
        matrix=fitz.Matrix(zoom, zoom), colorspace=fitz.csGRAY, alpha=False
    )
    gray = np.frombuffer(pixmap.samples, dtype=np.uint8).reshape(
        pixmap.height, pixmap.stride
    )[:, : pixmap.width]
    ink = gray < FIGURE_INK_THRESHOLD
    height_px, width_px = ink.shape

    def px_box(rect, pad=0.0):
        return (
            max(0, int((rect.y0 - page_rect.y0 - pad) * zoom)),
            min(height_px, int((rect.y1 - page_rect.y0 + pad) * zoom) + 1),
            max(0, int((rect.x0 - page_rect.x0 - pad) * zoom)),
            min(width_px, int((rect.x1 - page_rect.x0 + pad) * zoom) + 1),
        )

    # 1. Erase all real text — labels are handled as text, not ink.
    for rect in word_rects:
        y0, y1, x0, x1 = px_box(rect, 0.8)
        ink[y0:y1, x0:x1] = False

    # 2. Erase leader lines so they can't join two pictures.
    for _, far_point, near_point in leaders:
        steps = int(max(abs(far_point.x - near_point.x), abs(far_point.y - near_point.y)) * zoom) + 2

        for step in range(steps + 1):
            t = step / steps
            x = int((near_point.x + (far_point.x - near_point.x) * t - page_rect.x0) * zoom)
            y = int((near_point.y + (far_point.y - near_point.y) * t - page_rect.y0) * zoom)
            ink[max(0, y - 2):y + 3, max(0, x - 2):x + 3] = False

    # 3. Erase full-width bands and rules (header/footer decoration).
    full_rows = ink.sum(axis=1) >= 0.85 * width_px
    ink[full_rows] = False

    # 4. Down-sample to a coarse grid and join nearby ink.
    cell = max(1, int(round(FIGURE_CELL_PT * zoom)))
    rows, cols = height_px // cell, width_px // cell

    if rows == 0 or cols == 0:
        return []

    cells = ink[: rows * cell, : cols * cell].reshape(rows, cell, cols, cell).any(axis=(1, 3))
    reach = max(1, int(round(FIGURE_JOIN_GAP_PT / FIGURE_CELL_PT / 2)))
    joined = cells.copy()

    for shift in range(1, reach + 1):
        joined[shift:, :] |= cells[:-shift, :]
        joined[:-shift, :] |= cells[shift:, :]

    grown = joined.copy()

    for shift in range(1, reach + 1):
        grown[:, shift:] |= joined[:, :-shift]
        grown[:, :-shift] |= joined[:, shift:]

    component_grid, component_count = _connected_components(grown)
    component_grid = component_grid * cells

    if component_count == 0:
        return []

    def cell_rect(r0, c0, r1, c1):
        return fitz.Rect(
            page_rect.x0 + c0 * FIGURE_CELL_PT,
            page_rect.y0 + r0 * FIGURE_CELL_PT,
            page_rect.x0 + (c1 + 1) * FIGURE_CELL_PT,
            page_rect.y0 + (r1 + 1) * FIGURE_CELL_PT,
        )

    pieces = {}

    for component in range(1, component_count + 1):
        where = np.argwhere(component_grid == component)

        if len(where) == 0:
            continue

        (r0, c0), (r1, c1) = where.min(axis=0), where.max(axis=0)
        pieces[component] = {"rect": cell_rect(r0, c0, r1, c1), "cells": len(where)}

    page_area = page_rect.width * page_rect.height
    word_centres = [
        fitz.Point((r.x0 + r.x1) / 2, (r.y0 + r.y1) / 2) for r in word_rects
    ]

    def is_picture_sized(rect):
        return rect.width >= MIN_FIGURE_SIZE_PT and rect.height >= MIN_FIGURE_SIZE_PT

    def is_text_frame(rect, ink_cells):
        # A box around a note, or a table's ruled grid: a lot of text
        # inside, very little ink of its own.
        area_cells = max(1.0, (rect.width / FIGURE_CELL_PT) * (rect.height / FIGURE_CELL_PT))
        density = ink_cells / area_cells
        words_inside = sum(1 for point in word_centres if rect.contains(point))
        return words_inside >= 8 and density < 0.25

    figures = []
    fragments = []

    for component, piece in pieces.items():
        rect = piece["rect"]

        if rect.width * rect.height >= 0.7 * page_area:
            continue  # a scanned page / full-page background, not a figure

        if in_page_margin_band(rect):
            continue  # header/footer decoration, page-number badge

        if rect.width >= 0.5 * page_rect.width and rect.height <= 12:
            continue  # a horizontal rule

        if is_picture_sized(rect):
            if not is_text_frame(rect, piece["cells"]):
                figures.append({"components": [component], "ink": fitz.Rect(rect), "cells": piece["cells"]})
        else:
            fragments.append(component)

    # Small fragments right next to a picture are part of it.
    loose = []

    for component in fragments:
        rect = pieces[component]["rect"]
        nearest, best = None, FIGURE_FRAGMENT_ATTACH_PT

        for figure in figures:
            distance = _rect_distance(rect, figure["ink"])

            if distance <= best:
                nearest, best = figure, distance

        if nearest is None:
            loose.append(component)
        else:
            nearest["components"].append(component)
            nearest["ink"].include_rect(rect)
            nearest["cells"] += pieces[component]["cells"]

    # Small drawings with no picture nearby are grouped with each other
    # (a sketch made of several separate little shapes).
    groups = []

    for component in loose:
        rect = pieces[component]["rect"]
        touching = [
            group for group in groups
            if _rect_distance(rect, group["ink"]) <= FIGURE_FRAGMENT_GROUP_PT
        ]
        merged = {"components": [component], "ink": fitz.Rect(rect), "cells": pieces[component]["cells"]}

        for group in touching:
            merged["components"] += group["components"]
            merged["ink"].include_rect(group["ink"])
            merged["cells"] += group["cells"]
            groups.remove(group)

        groups.append(merged)

    for group in groups:
        if (
            is_picture_sized(group["ink"])
            and len(group["components"]) >= 2
            and group["cells"] >= 40
            and not is_text_frame(group["ink"], group["cells"])
        ):
            figures.append(group)

    if not figures:
        return []

    figures.sort(key=lambda f: f["cells"], reverse=True)
    figures = figures[:MAX_FIGURES_PER_PAGE]

    owner_of_component = np.zeros(component_count + 1, dtype=np.int32)

    for index, figure in enumerate(figures, start=1):
        for component in figure["components"]:
            owner_of_component[component] = index

    figure_grid = owner_of_component[component_grid]

    def nearest_figure(rect, reach):
        r0 = max(0, int((rect.y0 - page_rect.y0 - reach) / FIGURE_CELL_PT))
        r1 = min(rows, int((rect.y1 - page_rect.y0 + reach) / FIGURE_CELL_PT) + 1)
        c0 = max(0, int((rect.x0 - page_rect.x0 - reach) / FIGURE_CELL_PT))
        c1 = min(cols, int((rect.x1 - page_rect.x0 + reach) / FIGURE_CELL_PT) + 1)
        window = figure_grid[r0:r1, c0:c1]
        hits = np.argwhere(window > 0)

        if len(hits) == 0:
            return None, None

        ys = page_rect.y0 + (hits[:, 0] + r0 + 0.5) * FIGURE_CELL_PT
        xs = page_rect.x0 + (hits[:, 1] + c0 + 0.5) * FIGURE_CELL_PT
        dx = np.maximum(0, np.maximum(rect.x0 - xs, xs - rect.x1))
        dy = np.maximum(0, np.maximum(rect.y0 - ys, ys - rect.y1))
        distance = np.sqrt(dx * dx + dy * dy)
        best = int(np.argmin(distance))

        if distance[best] > reach:
            return None, None

        return int(window[hits[best, 0], hits[best, 1]]) - 1, float(distance[best])

    for figure in figures:
        figure["labels"] = []

    # Labels: the leader line decides; otherwise the nearest ink wins.
    leader_owner = {}

    for label_index, far_point, _ in leaders:
        owner, _ = nearest_figure(fitz.Rect(far_point, far_point), 6)

        if owner is not None:
            leader_owner.setdefault(label_index, owner)

    for index, label in enumerate(labels):
        owner = leader_owner.get(index)

        if owner is None:
            owner, _ = nearest_figure(label["rect"], FIGURE_LABEL_REACH_PT)

        if owner is not None:
            figures[owner]["labels"].append(label)

    # Captions: a caption describes every picture above it in its
    # column. Its text is kept as context for the AI (with the textbook
    # numbering stripped); it is never drawn into an image.
    for figure in figures:
        figure["caption"] = ""

    for caption_rect, caption_text in sorted(captions, key=lambda item: item[0].y0):
        for figure in figures:
            ink_rect = figure["ink"]
            gap = caption_rect.y0 - ink_rect.y1
            overlaps_x = caption_rect.x0 - 30 < ink_rect.x1 and caption_rect.x1 + 30 > ink_rect.x0

            if not (-6 <= gap <= FIGURE_CAPTION_GROUP_REACH_PT and overlaps_x) or figure["caption"]:
                continue

            blocked = any(
                block.y0 >= ink_rect.y1 - 2
                and block.y1 <= caption_rect.y0 + 2
                and block.x0 < max(ink_rect.x1, caption_rect.x1)
                and block.x1 > min(ink_rect.x0, caption_rect.x0)
                for block in body
            )

            if not blocked:
                figure["caption"] = caption_text

    leaders_by_label = {}

    for label_index, far_point, near_point in leaders:
        leaders_by_label.setdefault(label_index, []).append((far_point, near_point))

    label_index_of = {id(label): index for index, label in enumerate(labels)}
    results = []

    for index, figure in enumerate(figures):
        figure_labels = []

        for label in figure["labels"]:
            figure_labels.append(
                {
                    "rect": fitz.Rect(label["rect"]),
                    "text": label["text"],
                    "leaders": leaders_by_label.get(label_index_of[id(label)], []),
                    "line_height": label.get("line_height", label["rect"].height),
                }
            )

        crop = fitz.Rect(figure["ink"])
        crop = fitz.Rect(
            crop.x0 - FIGURE_PADDING_PT,
            crop.y0 - FIGURE_PADDING_PT,
            crop.x1 + FIGURE_PADDING_PT,
            crop.y1 + FIGURE_PADDING_PT,
        ) & page_rect

        if crop.is_empty:
            continue

        results.append(
            {
                "rect": crop,
                "ink": fitz.Rect(figure["ink"]),
                "grid_index": index + 1,
                "grid": figure_grid,
                "labels": figure_labels,
                "caption": figure["caption"],
            }
        )

    results.sort(key=lambda item: (round(item["rect"].y0 / 12), item["rect"].x0))

    return results


# How the printed labels of a figure are handled in the image that goes
# into the question bank. Labels (part names, panel letters, figure
# numbers, captions) are never shown as printed: they would give the
# answer away.
FIGURE_LABEL_MODES = {
    "Remove all labels (picture only)": "hide",
    "Replace labels with letters A, B, C…": "letters",
}
DEFAULT_FIGURE_LABEL_MODE = "Remove all labels (picture only)"

_HAS_LETTER_RE = re.compile(r"[^\W\d_]")
_FIGURE_NUMBER_RE = re.compile(
    r"\b(?:fig(?:ure)?s?)\.?\s*\d+(?:\s*\.\s*\d+)*\s*(?:\(\s*[a-z]\s*\)|[a-z]\b)?",
    re.IGNORECASE,
)
_PANEL_ID_RE = re.compile(r"\(\s*([a-z])\s*\)|^\s*([a-z])\s*$", re.IGNORECASE)


def strip_figure_numbering(text):
    """'Figure 7.1 Simple epithelium' -> 'Simple epithelium'."""

    cleaned = _FIGURE_NUMBER_RE.sub("", str(text or ""))
    return re.sub(r"\s{2,}", " ", cleaned).strip(" :;,.-")


_FIGURE_REFERENCE_RE = re.compile(
    r"(?:\bthe\s+)?\bfig(?:ure)?s?\b\.?\s*\d+(?:\s*\.\s*\d+)*"
    r"(?:\s*\(\s*[a-z]\s*\)|[a-z]\b)?"
    r"(?:\s*(?:,|and|&|or)\s*(?:fig(?:ure)?s?\b\.?\s*)?\d+(?:\s*\.\s*\d+)*"
    r"(?:\s*\(\s*[a-z]\s*\)|[a-z]\b)?)*",
    re.IGNORECASE,
)
_TEXTBOOK_REFERENCE_RE = re.compile(
    r"\b(?:ncert|textbook|this chapter|the chapter|source (?:page|text|pdf))\b",
    re.IGNORECASE,
)
_USES_FIGURE_RE = re.compile(
    r"\b(?:figure|diagram|image|picture|illustration|shown|marked|given below)\b",
    re.IGNORECASE,
)


def neutralize_figure_references(text):
    """
    'Refer to Figure 7.1 given below' -> 'Refer to the figure given below';
    'Figures 7.5(a) and 7.5(b)' -> 'the given figure'. Textbook figure
    numbers must never reach the question bank.
    """

    text = str(text or "")

    if not text:
        return text

    text = _FIGURE_REFERENCE_RE.sub("the given figure", text)
    text = re.sub(r"\bthe given figure(\s+given)?\s+below\b", "the figure given below", text, flags=re.IGNORECASE)
    text = re.sub(r"\b(the|a|an)\s+the given figure\b", "the given figure", text, flags=re.IGNORECASE)
    text = re.sub(r"(^|[.!?]\s+)the given figure", lambda m: m.group(1) + "The given figure", text)
    text = re.sub(r"(^|[.!?]\s+)the figure given below", lambda m: m.group(1) + "The figure given below", text)
    return re.sub(r"[ \t]{2,}", " ", text).strip()


def _describe_label(text):
    """Splits a printed label into its part name and panel letter."""

    panel = None
    match = _PANEL_ID_RE.search(text)

    if match:
        panel = (match.group(1) or match.group(2) or "").lower() or None

    name = _PANEL_ID_RE.sub(" ", text)
    name = re.sub(r"\s{2,}", " ", name).strip(" ,;:-")

    return name, panel


def _foreign_ink_masks(item, clip, page_rect):
    """Cells of OTHER pictures' ink inside `clip`, as rectangles to blank."""

    grid = item["grid"]
    rows, cols = grid.shape
    r0 = max(0, int((clip.y0 - page_rect.y0) / FIGURE_CELL_PT))
    r1 = min(rows, int((clip.y1 - page_rect.y0) / FIGURE_CELL_PT) + 1)
    c0 = max(0, int((clip.x0 - page_rect.x0) / FIGURE_CELL_PT))
    c1 = min(cols, int((clip.x1 - page_rect.x0) / FIGURE_CELL_PT) + 1)
    window = grid[r0:r1, c0:c1]
    foreign = (window > 0) & (window != item["grid_index"])
    masks = []

    for row_offset, row in enumerate(foreign):
        col = 0

        while col < len(row):
            if not row[col]:
                col += 1
                continue

            run_start = col

            while col < len(row) and row[col]:
                col += 1

            masks.append(
                fitz.Rect(
                    page_rect.x0 + (c0 + run_start) * FIGURE_CELL_PT,
                    page_rect.y0 + (r0 + row_offset) * FIGURE_CELL_PT,
                    page_rect.x0 + (c0 + col) * FIGURE_CELL_PT,
                    page_rect.y0 + (r0 + row_offset + 1) * FIGURE_CELL_PT,
                )
            )

    return masks


def _prepare_clean_page(page, detected, label_mode):
    """
    Removes, from a scratch copy of the page, everything that must not
    appear in figure images: every word (labels, panel letters, figure
    numbers, captions, body text) and — when labels are removed — the
    pointer lines that led to them. Pure numbers are kept (a graph's
    axis values). In "letters" mode each pointed label is replaced by a
    neutral letter (A, B, C, ...) and its pointer line is kept, so a
    question can ask about "the part marked A".

    Returns, per detected figure, the list of (letter, part name) pairs
    placed on it, and the rectangles the letters occupy.
    """

    try:
        words = page.get_text("words")
    except Exception:
        words = []

    for x0, y0, x1, y1, text, *_ in words:
        if _HAS_LETTER_RE.search(text):
            page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=None, cross_out=False)

    page.apply_redactions(
        images=fitz.PDF_REDACT_IMAGE_NONE,
        graphics=fitz.PDF_REDACT_LINE_ART_NONE,
    )

    if label_mode != "letters":
        removed_any = False

        for figure in detected:
            for label in figure["labels"]:
                for _, near_point in label["leaders"]:
                    touch = fitz.Rect(
                        near_point.x - 0.6, near_point.y - 0.6,
                        near_point.x + 0.6, near_point.y + 0.6,
                    )
                    page.add_redact_annot(touch, fill=None, cross_out=False)
                    removed_any = True

        if removed_any:
            page.apply_redactions(
                images=fitz.PDF_REDACT_IMAGE_NONE,
                graphics=fitz.PDF_REDACT_LINE_ART_REMOVE_IF_TOUCHED,
                text=getattr(fitz, "PDF_REDACT_TEXT_NONE", 1),
            )

        return [[] for _ in detected], [[] for _ in detected]

    markers_per_figure = []
    marker_rects_per_figure = []

    for figure in detected:
        pointed = [label for label in figure["labels"] if label["leaders"]]
        pointed.sort(key=lambda label: (round(label["rect"].y0 / 6), label["rect"].x0))
        markers = []
        marker_rects = []

        for letter_index, label in enumerate(pointed[:26]):
            letter = chr(ord("A") + letter_index)
            name, _ = _describe_label(label["text"])
            near_point = label["leaders"][0][1]
            rect = label["rect"]
            size = max(8.0, min(11.0, label["line_height"] * 1.15))
            # Put the letter on the label's edge nearest the pointer line.
            x = min(max(near_point.x, rect.x0), rect.x1)
            y = min(max(near_point.y, rect.y0), rect.y1)
            x = x - size * 0.75 if x >= rect.x1 - 0.5 else x + 1

            origin = fitz.Point(x, y + size * 0.35)
            page.insert_text(origin, letter, fontsize=size, fontname="hebo", color=(0, 0, 0))
            markers.append((letter, name or label["text"]))
            marker_rects.append(fitz.Rect(origin.x - 1, origin.y - size, origin.x + size * 0.8, origin.y + 2))

        markers_per_figure.append(markers)
        marker_rects_per_figure.append(marker_rects)

    return markers_per_figure, marker_rects_per_figure


def _encode_figure(page, clip, masks, max_width_px, max_bytes):
    """
    Renders one figure crop, blanks its masks, and encodes it as PNG
    (sharp line art) or JPEG (photos/shaded art), whichever is smaller
    for the same look — stepping resolution down until it fits the
    size budget, so every image stays within a few tens/hundreds of KB.
    """

    zoom = max(1.0, min(4.0, max_width_px / max(clip.width, 1.0)))
    best = None

    for _ in range(6):
        matrix = fitz.Matrix(zoom, zoom)
        pixmap = page.get_pixmap(matrix=matrix, clip=clip, alpha=False)

        for mask in masks:
            area = (mask * matrix).irect & pixmap.irect

            if not area.is_empty:
                pixmap.set_rect(area, (255, 255, 255))

        png = pixmap.tobytes("png")
        jpeg = pixmap.tobytes("jpeg", jpg_quality=85)

        if len(png) <= 1.3 * len(jpeg):
            candidate = (png, "image/png")
        else:
            candidate = (jpeg, "image/jpeg")

        best = candidate

        if len(candidate[0]) <= max_bytes:
            break

        zoom = max(0.8, zoom * 0.8)

    return best


@st.cache_data(show_spinner=False)
def extract_all_page_source_images(
    pdf_bytes,
    label_mode="hide",
    size_preset=DEFAULT_FIGURE_SIZE_PRESET,
):
    """
    Returns {page_number: [figure, ...]} where each figure is
      {"image": bytes, "mime": "image/png" | "image/jpeg",
       "width_pt", "height_pt", "size_kb",
       "caption": str   — what the figure shows, numbering stripped
       "panel": str     — panel letter from the source, e.g. "a" (or "")
       "parts": [str]   — names of the parts the source labelled
       "markers": [(letter, part name)] — letters drawn on the image}
    — every separate picture on the source page, cropped from the page
    with ALL printed text removed (part names, panel letters, figure
    numbers, captions), so the image shows the picture only; in
    "letters" mode, pointed labels become neutral letters instead.
    Nothing is drawn or invented; a page with no picture gets [].

    Cached on the PDF bytes + options, so widget clicks after upload
    don't redo the work.
    """

    if fitz is None:
        return {}

    max_width_px, max_bytes = FIGURE_SIZE_PRESETS.get(
        size_preset, FIGURE_SIZE_PRESETS[DEFAULT_FIGURE_SIZE_PRESET]
    )
    page_images = {}
    pdf_document = None
    clean_document = None

    try:
        pdf_document = fitz.open(stream=pdf_bytes, filetype="pdf")
        clean_document = fitz.open(stream=pdf_bytes, filetype="pdf")

        for page_index in range(len(pdf_document)):
            page_number = page_index + 1
            figures = []

            try:
                page = pdf_document.load_page(page_index)
                detected = _detect_page_figures(page)

                if detected:
                    clean_page = clean_document.load_page(page_index)
                    markers_per_figure, marker_rects_per_figure = _prepare_clean_page(
                        clean_page, detected, label_mode
                    )
                else:
                    clean_page = None

                for item, markers, marker_rects in zip(
                    detected, markers_per_figure if detected else [], marker_rects_per_figure if detected else []
                ):
                    clip = fitz.Rect(item["rect"])

                    for rect in marker_rects:
                        clip.include_rect(rect)

                    clip = fitz.Rect(
                        clip.x0 - 2, clip.y0 - 2, clip.x1 + 2, clip.y1 + 2
                    ) & clean_page.rect

                    masks = _foreign_ink_masks(item, clip, clean_page.rect)

                    for other_rects in marker_rects_per_figure:
                        if other_rects is marker_rects:
                            continue

                        masks.extend(rect for rect in other_rects if rect.intersects(clip))

                    try:
                        data, mime = _encode_figure(
                            clean_page,
                            clip,
                            masks,
                            max_width_px,
                            max_bytes,
                        )
                    except Exception:
                        # One figure failing to render shouldn't take
                        # down the rest of the page.
                        continue

                    parts = []
                    panel = ""

                    for label in item["labels"]:
                        name, label_panel = _describe_label(label["text"])

                        if label_panel and not panel:
                            panel = label_panel

                        if name and _HAS_LETTER_RE.search(name):
                            parts.append(strip_figure_numbering(name) or name)

                    figures.append(
                        {
                            "image": data,
                            "mime": mime,
                            "width_pt": clip.width,
                            "height_pt": clip.height,
                            "caption": strip_figure_numbering(item["caption"]),
                            "panel": panel,
                            "parts": parts,
                            "markers": markers,
                            "size_kb": max(1, round(len(data) / 1024)),
                        }
                    )

            except Exception:
                figures = []

            page_images[page_number] = figures

    except Exception:
        return {}

    finally:
        for document in (pdf_document, clean_document):
            if document is not None:
                document.close()

    return page_images


# ---------------------------------------------------------------------------
# PROMPTS
# ---------------------------------------------------------------------------
def build_generation_system_prompt(
    exam_mode,
    subject,
    question_type,
    figure_count=0,
    figures_visible=False,
):
    if exam_mode == "NEET":
        exam_rules = """
NEET STANDARD:
- Create original NEET-level questions, not reading-comprehension questions.
- Biology: NCERT-aligned mechanisms, comparisons, sequences, experiments,
  exceptions, diagrams, and misconceptions.
- Physics: formula application, units, graphs, limiting cases, and concepts.
- Chemistry: reactions, mechanisms, trends, calculations, structures, and exceptions.
- Prefer Understand, Apply, Analyze, and Evaluate.
"""
    elif exam_mode == "JEE Main":
        exam_rules = """
JEE MAIN STANDARD:
- Use application-based and calculation-based questions.
- Build realistic distractors from common errors.
- Mathematics and Physics must require formula use or reasoning.
- Chemistry must test reactions, trends, mechanisms, or calculations.
"""
    elif exam_mode == "JEE Advanced":
        exam_rules = """
JEE ADVANCED STANDARD:
- Use multi-step, analytical, non-routine questions.
- Test relationships, limiting cases, and deep reasoning.
- Avoid one-line factual questions.
"""
    else:
        exam_rules = """
TEXTBOOK PRACTICE STANDARD:
- Still create concept-based questions.
- Do not copy sentences or ask what the passage says.
"""

    if question_type == "MCQ":
        type_rules = """
MCQ:
- Exactly four distinct and plausible options.
- Options must be from the same conceptual category.
- key must be exactly "1", "2", "3", or "4".
"""
    else:
        type_rules = """
NUMERICAL:
- options must be [] and key must be the final numerical answer as a string.
- Include units where needed and show the essential calculation.
"""

    difficulty_rules = """
DIFFICULTY VS LENGTH — these are NOT the same thing:
- A "Hard" question is conceptually tricky: multi-step reasoning, a
  subtle or closely-spaced set of distractors, an edge case or
  exception to the general rule, a common student misconception
  used as a trap option, or combining two individually-simple ideas.
- A "Hard" question is NOT simply a longer sentence, a wordier stem,
  or more clauses stacked together. Padding a question with extra
  words does not make it harder — it just makes it harder to read.
- An "Easy" question can still be phrased precisely and completely;
  it does not need to be cut down to a one-line fragment.
- Judge difficulty by how many genuine reasoning steps a well-
  prepared student needs and how easy it is to eliminate wrong
  options — never by word count. Keep every question as concise as
  it can be while still being unambiguous, regardless of difficulty.
"""

    # Figures are never drawn/invented by the model. The lecturer
    # picks real figures cropped from the source page; each one is
    # listed in the user prompt as F1, F2, ... with its caption and
    # printed labels, and every one of them must get a question.
    if figure_count > 0:
        seeing = (
            "The figure images are attached to this message in the same "
            "order (F1 first) exactly as the student will see them. Look "
            "at them."
            if figures_visible
            else "You cannot see the images; the description of each "
            "figure below tells you what it shows."
        )
        diagram_rules = f"""
SOURCE FIGURES (selected by the lecturer):
- {figure_count} picture(s) from this source page are listed in the
  user message as F1, F2, ... {seeing}
- Write AT LEAST ONE question for EVERY listed figure and put that
  figure's id in the question's "figure_id" field. The picture is
  printed inside the question, right after the question text.
- The student sees ONLY the picture: every printed label, part name,
  panel letter, figure number and caption has been REMOVED from it
  (or, where stated, replaced by neutral letters A, B, C ...). The
  figure description you are given is answer-key context for you —
  the student does not see it.
- Frame each figure question OUT OF THE PICTURE: the student must
  look at the picture to answer. Refer to it only as "the figure
  given below", "the diagram given below" or "the given figure".
  Good patterns:
    * "Identify the tissue shown in the figure given below."
    * "The tissue shown in the figure given below is found in:"
    * "The cells shown in the figure given below are specialised for:"
    * "Which feature visible in the figure given below ..."
    * with letters: "The part marked A in the figure given below is:"
      / "What is the function of the structure marked B?"
- NEVER name, in the question text, the tissue/organ/structure that
  the picture shows (that is what the student must work out from the
  picture). Its name may appear only among the options/answer.
- NEVER write figure numbers or textbook references in any field:
  no "Figure 7.1", "Fig. 7.2(a)", "(a)"/"(b)" panel letters,
  "NCERT", "textbook", "chapter" or "page".
- A question that does not need the picture must use "figure_id": "".
"""
    else:
        diagram_rules = """
SOURCE FIGURES:
- No figures are attached for this page — always use "figure_id": "".
"""

    diagram_rules += """
- Questions with "figure_id": "" are text-only: they must NOT mention
  or depend on any figure, diagram, image or table, and must never
  cite figure numbers ("Figure 7.1", "Fig. 7.2(a)") or the textbook.
- Write every field in English only.
"""

    return f"""You are a senior {subject} faculty member and expert
{exam_mode} question setter.

EXAM: {exam_mode}
SUBJECT: {subject}

{exam_rules}
{type_rules}
{difficulty_rules}
{diagram_rules}

SOURCE USAGE:
The source page is a knowledge base, not text to copy. First identify the
underlying concepts, mechanisms, relationships, formulas, exceptions, and
misconceptions. Then construct an original question.

STRICTLY REJECT:
- According to the passage...
- What does the passage say?
- What is mentioned in the text?
- What does the author state?
- Direct sentence-to-question conversion.
- Answers copied from one sentence.
- Generic reading-comprehension questions.
- Random facts outside the selected topic/exam.
- Chinese, Arabic, Cyrillic, Japanese, Korean, or unexpected scripts.

FORMULA FORMAT — the software fully renders all of the notation
below (as proper Word superscripts/subscripts, stacked fractions,
and radical signs with a full bar over the entire expression, not
just the symbol) — use whichever form is natural, LaTeX-style
commands or the raw Unicode character, both are supported:
- Superscript: ^{{...}}, for example x^{{2}}, r^{{n}}, Na^{{+}}.
- Subscript: _{{...}}, for example S_{{n}}, H_{{2}}O, SO_{{4}}^{{2-}}.
- Isotope notation: ^{{35}}_{{17}}Cl (mass number then atomic
  number, immediately before the element symbol).
- Combinatorics: ^{{n}}C_{{r}}, ^{{n}}P_{{r}}.
- Fractions: a/b, (a+b)/(c+d), or \\frac{{a}}{{b}} — always wrap a
  multi-term numerator or denominator in parentheses.
- Roots: √41, √(9+16+16), \\sqrt{{x}}, or \\sqrt[3]{{8}} for an nth
  root — always wrap a multi-term radicand in parentheses so the
  radical bar covers the whole expression correctly.
- Greek letters: \\alpha, \\beta, \\theta, \\lambda, \\pi, \\Delta,
  \\Omega, etc., or the Unicode letter directly (α, β, θ, λ, π, Δ, Ω).
- Calculus/operators: \\sum, \\prod, \\int, \\partial, \\nabla,
  \\lim, \\infty, \\propto, \\approx, \\neq, \\leq, \\geq.
- Set theory/logic (Mathematics): \\in, \\subset, \\cup, \\cap,
  \\forall, \\exists, \\Rightarrow, \\Leftrightarrow, \\mathbb{{R}},
  \\mathbb{{N}}, \\mathbb{{Z}}, \\mathbb{{Q}}, \\mathbb{{C}}.
- Vectors/derivatives (Physics): \\vec{{F}}, \\hat{{n}}, \\dot{{x}},
  \\ddot{{x}}, dy/dx, \\frac{{d^{{2}}y}}{{dx^{{2}}}}.
- Reaction arrows (Chemistry): \\rightarrow, \\rightleftharpoons for
  equilibrium, \\xrightarrow{{\\Delta}} for a heating condition above
  the arrow, \\xrightarrow[Ni]{{\\Delta}} for a condition above and a
  catalyst below.
- Degrees/primes: 30^\\circ or 30°; x' or x^\\prime.
- Do not invent notation the list above has no equivalent for (e.g.
  hand-drawn electron-pushing arrows, images) — describe it in words
  instead.

Return STRICT JSON ONLY:
{{
  "questions": [
    {{
      "question_type": "MCQ" or "Numerical",
      "concept_id": "short_snake_case_tag_for_the_exact_fact_or_mechanism_tested",
      "concept_tested": "string",
      "question_style": "Conceptual | Application | Statement-based | Numerical | Diagram-based | Experimental",
      "requires_reasoning": true,
      "bloom_level": "Understand | Apply | Analyze | Evaluate",
      "difficulty": "Easy | Medium | Hard",
      "question": "string",
      "options": ["string", "string", "string", "string"] for MCQ or [] for Numerical,
      "key": "MCQ option number 1-4 as a string; Numerical final answer as a string",
      "explanation": "string",
      "source_concepts": ["string"],
      "exam_relevance": "string",
      "figure_id": "F1" (the id of the listed source figure this question is about) or "" for a question that is not about a figure
    }}
  ]
}}

concept_id rules:
- 2-6 lowercase words joined by underscores, naming the SPECIFIC fact,
  mechanism, comparison, or rule the question tests — not the topic.
- Example: "binomial_nomenclature_two_word_rule", not "nomenclature".
- Two questions that test the same underlying fact must use the same
  (or a near-identical) concept_id, even if you word the questions
  differently.

Return exactly the requested number of questions and no commentary."""


def build_generation_user_prompt(
    exam_mode,
    subject,
    topic,
    subtopic,
    page_text,
    number_of_questions,
    difficulty,
    question_type,
    image_context,
    already_tested_concepts,
):
    if already_tested_concepts:
        # Cap what's shown in the prompt so it stays short even on a
        # 15-page / 60-question run; validation still checks the full
        # accumulated list regardless of what's shown here.
        concept_lines = "\n".join(
            f"- {item['id']} ({item['text']})"
            if item.get("text")
            else f"- {item['id']}"
            for item in already_tested_concepts[-50:]
            if item.get("id")
        )

        avoid_block = f"""
CONCEPT IDS ALREADY TESTED EARLIER IN THIS RUN (do not repeat any of
these facts/mechanisms, even with different wording, numbers, or
examples — pick a different concept_id):
{concept_lines}
"""
    else:
        avoid_block = ""

    return f"""Exam: {exam_mode}
Subject: {subject}
Topic: {topic}
Sub-topic: {subtopic}
Question type: {question_type}
Difficulty: {difficulty}

SOURCE PAGE CONTENT:
---
{page_text}
---

{image_context}
{avoid_block}
Analyse the concepts and generate exactly {number_of_questions}
original {exam_mode}-level questions.

Do not ask generic passage questions.
Do not copy source sentences.
Do not retest any concept_id listed above — pick a different fact,
mechanism, comparison, or application from the source page instead.
In the "explanation" field, give ONLY the final justification for the
stored "key". Do not think out loud, do not second-guess yourself, and
do not mention or argue for any option other than the correct one.
Return JSON only."""


# ---------------------------------------------------------------------------
# EXTRACT-MODE PROMPT (transcribe pre-existing questions from an image,
# rather than generate new ones)
# ---------------------------------------------------------------------------
EXTRACTION_SYSTEM_PROMPT = """You are transcribing exam questions EXACTLY as they appear in the given page content (an image of the page, or its already-extracted text) — you are not solving, generating, rewording, or correcting anything.

The page content may be messy — mixed-up column order, run-together lines, stray page numbers/headers — because it may come from a raw PDF text layer rather than a clean image. Your job is to recognize the actual question/option/answer-key structure underneath that mess and transcribe it faithfully, the same structured-extraction task regardless of source format. This is NOT an invitation to reword, "clean up", or paraphrase the content itself — only to correctly figure out where one question ends and the next begins, and to correctly match each answer key to its question (which may be listed in a separate answer-key section, not right after the question itself).

For every distinct question found, in the order it appears, produce one object:
{
  "question": "the question stem, transcribed exactly as printed. Represent math/symbols as plain text (e.g. x^2, sqrt(x), fractions as a/b) rather than image references.",
  "options": ["option text", "option text", "option text", "option text"] in the order printed, if the question is multiple choice. Use an empty list [] if the question has no listed options (e.g. a numerical/short-answer question).
  "key": the correct option EXACTLY as it identifies the answer (a number like "1"-"4", a letter like "A"-"D", or the option's own text) if — and only if — the answer/solution for this specific question is shown somewhere in the given content (an answer key section, a circled/marked/bolded option, a worked solution, etc — including an answer key table elsewhere on the same page). Set this to null if no answer is shown anywhere for this question. NEVER guess, solve, or infer an answer that isn't explicitly given.
  "explanation": the solution/explanation text exactly as given for this question, if present, else null. Do not write your own explanation.
}

Rules:
- Transcribe faithfully: keep numbers, units, symbols and option order exactly as given.
- Do not skip any question, and do not merge separate questions into one.
- Do not invent content that isn't present in the given page content.
- If the page has no questions at all (e.g. a cover page or blank page), return {"questions": []}.

Return strict JSON only, no markdown code fences, no commentary:
{"questions": [ ... ]}"""


VISION_MAX_IMAGE_SIDE_PX = 2000
VISION_MAX_IMAGE_BYTES = 3_500_000


def prepare_image_for_vision(data, mime="image/png"):
    """
    Makes an uploaded image safe for any vision model:
      - transparent backgrounds are filled with a colour that contrasts
        with the text (a transparent PNG with white text — common for
        screenshots from dark-mode apps — would otherwise reach the
        model as white-on-white or black-on-black and be unreadable);
      - very large photos are scaled down (APIs reject or slow down on
        multi-megabyte images);
      - any format PyMuPDF can read is re-encoded as PNG/JPEG.
    Returns (bytes, mime). Falls back to the original on any error.
    """

    if fitz is None or not data:
        return data, mime

    try:
        pixmap = fitz.Pixmap(data)

        if pixmap.colorspace is None or pixmap.colorspace.n not in (1, 3):
            pixmap = fitz.Pixmap(fitz.csRGB, pixmap)

        if pixmap.alpha:
            channels = pixmap.n
            array = np.frombuffer(pixmap.samples, dtype=np.uint8).reshape(
                pixmap.height, pixmap.width, channels
            ).astype(np.float32)
            colour, alpha = array[..., :-1], array[..., -1:] / 255.0
            visible = alpha[..., 0] > 0.5

            if visible.any():
                ink_brightness = float(colour[visible].mean())
            else:
                ink_brightness = 0.0

            background = 0.0 if ink_brightness > 140 else 255.0
            flat = colour * alpha + background * (1.0 - alpha)
            flat = np.clip(flat, 0, 255).astype(np.uint8)

            if flat.shape[-1] == 1:
                flat = np.repeat(flat, 3, axis=-1)

            pixmap = fitz.Pixmap(
                fitz.csRGB, pixmap.width, pixmap.height, flat.tobytes(), 0
            )

        longest = max(pixmap.width, pixmap.height)

        if longest > VISION_MAX_IMAGE_SIDE_PX:
            scale = VISION_MAX_IMAGE_SIDE_PX / longest
            pixmap = fitz.Pixmap(
                pixmap, max(1, int(pixmap.width * scale)), max(1, int(pixmap.height * scale))
            )

        png = pixmap.tobytes("png")

        if len(png) <= VISION_MAX_IMAGE_BYTES:
            return png, "image/png"

        return pixmap.tobytes("jpeg", jpg_quality=85), "image/jpeg"
    except Exception:
        return data, mime


# ---------------------------------------------------------------------------
# EXTRACT MODE WITHOUT AI: rule-based question reader
#
# Turns plain text (from a PDF's text layer, or from OCR of an image)
# into {"question", "options", "key", "explanation"} items — the same
# shape the AI extraction returns — without calling any AI model.
# Handles the common question-paper layouts: "Q1:" / "Q.1" / "1."
# numbering; options as "1." / "(1)" / "(a)" / "a)" / "A." on their own
# lines or several on one line; "Ans: (b)" / "Answer: 2" lines;
# "Solution:" / "Explanation:" text; and an "Answer Key" table at the end.
# ---------------------------------------------------------------------------
_PREFIXED_QUESTION_RE = re.compile(
    r"^\s*(?:Q(?:ues(?:tion)?)?|Que)\s*\.?\s*(?:No\.?\s*)?(\d{1,3})\s*[:.)\-]?\s*(.*)$",
    re.IGNORECASE,
)
_NUMBERED_LINE_RE = re.compile(r"^\s*\(?\s*(\d{1,3})\s*[.)]\s*(.*)$")
_OPTION_LINE_RE = re.compile(
    r"^\s*(?:\(\s*([a-dA-D1-4])\s*\)|([a-dA-D])\s*[.)]|([1-4])\s*[.)])\s*(.*)$"
)
_INLINE_OPTION_RE = re.compile(r"(?:^|\s)\(\s*([a-dA-D1-4])\s*\)\s*|(?:^|\s)([a-dA-D])\)\s+")
_ANSWER_LINE_RE = re.compile(
    r"^\s*(?:ans(?:wer)?|correct\s+(?:answer|option)|key)\s*[:.\-)]*\s*"
    r"(?:option\s*)?\(?\s*([a-dA-D1-4])\s*\)?(?=\W|$)",
    re.IGNORECASE,
)
_SOLUTION_LINE_RE = re.compile(
    r"^\s*(?:sol(?:ution)?|explanation|hint)\s*[:.\-)]\s*(.*)$", re.IGNORECASE
)
_ANSWER_KEY_HEADER_RE = re.compile(
    r"^\s*(?:answer\s*key|answers?|key\s*answers?)\s*[:\-]?\s*$", re.IGNORECASE
)
_ANSWER_KEY_PAIR_RE = re.compile(r"(\d{1,3})\s*[.):\-]?\s*\(?\s*([a-dA-D1-4])\s*\)?(?=\s|,|;|$)")


def _option_index(label):
    label = label.strip()

    if label.isdigit():
        return int(label)

    return ord(label.lower()) - ord("a") + 1


def _option_style(label):
    if label.isdigit():
        return "number"

    return "upper" if label.isupper() else "lower"


def _split_inline_options(line):
    """'(a) x (b) y (c) z (d) w' -> [('a','x'), ('b','y'), ...] or []."""

    markers = list(_INLINE_OPTION_RE.finditer(line))

    if len(markers) < 2:
        return []

    labels = [(m.group(1) or m.group(2)) for m in markers]
    indexes = [_option_index(label) for label in labels]

    # Only a run of consecutive labels (a, b, c...) counts as options.
    if indexes != list(range(indexes[0], indexes[0] + len(indexes))):
        return []

    if markers[0].start() > 0 and line[: markers[0].start()].strip():
        return []

    parts = []

    for position, marker in enumerate(markers):
        end = markers[position + 1].start() if position + 1 < len(markers) else len(line)
        parts.append((labels[position], line[marker.end():end].strip()))

    return parts


# Dimensional formulas: OCR flattens exponents ("[M1L1T-3K-1]").
_DIMENSION_BRACKET_RE = re.compile(r"\[\s*((?:[MLTKAIJNθ]\s*(?:-?\s*\d+)?\s*){2,})\]", re.IGNORECASE)
_DIMENSION_TERM_RE = re.compile(r"([MLTKAIJNθ])\s*(-?\s*\d+)?", re.IGNORECASE)
_SUPERSCRIPT_DIGITS = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻", "0123456789-")


def restore_dimension_exponents(text):
    """'[M1 L1 T-3k-1]' -> '[M^{1}L^{1}T^{-3}K^{-1}]' (only inside [...])."""

    def fix(match):
        terms = _DIMENSION_TERM_RE.findall(match.group(1))
        rebuilt = []

        for symbol, power in terms:
            symbol = symbol.upper() if symbol.lower() != "θ" else "θ"
            power = power.replace(" ", "")
            rebuilt.append(f"{symbol}^{{{power}}}" if power else symbol)

        return "[" + "".join(rebuilt) + "]"

    return _DIMENSION_BRACKET_RE.sub(fix, str(text or "").translate(_SUPERSCRIPT_DIGITS))


def _merge_minus_signs(variants):
    """
    OCR often drops the thin minus of a small raised exponent, but
    practically never invents one. Given several readings of the same
    line (at different zoom levels), keep the first reading and add
    every minus sign that ANY reading saw — when the readings agree on
    everything else.
    """

    def skeleton(text):
        return re.sub(r"[\s\-−–]", "", text.translate(_SUPERSCRIPT_DIGITS))

    base = variants[0].translate(_SUPERSCRIPT_DIGITS).replace("−", "-").replace("–", "-")
    base_skeleton = skeleton(base)
    minus_before = set()

    for variant in variants:
        variant = variant.translate(_SUPERSCRIPT_DIGITS).replace("−", "-").replace("–", "-")

        if skeleton(variant) != base_skeleton:
            continue

        position = 0
        pending_minus = False

        for char in variant:
            if char == "-":
                pending_minus = True
            elif not char.isspace():
                if pending_minus:
                    minus_before.add(position)
                pending_minus = False
                position += 1

    rebuilt = []
    position = 0
    previous = ""

    for char in base:
        if char == "-" or char.isspace():
            rebuilt.append(char)
            if char == "-":
                previous = "-"
            continue

        if position in minus_before and previous != "-":
            rebuilt.append("-")

        rebuilt.append(char)
        previous = char
        position += 1

    return "".join(rebuilt)


_FORMULA_HINT_RE = re.compile(r"[A-Za-z]\s*[-−]?\s*\d|\d\s*[A-Za-z]")
OCR_MAX_PASS_SIDE_PX = 5000


@st.cache_resource(show_spinner=False)
def get_ocr_engine():
    """The built-in OCR engine (RapidOCR, runs locally — no AI, no key)."""

    try:
        from rapidocr import RapidOCR
    except Exception:
        return None

    try:
        return RapidOCR()
    except Exception:
        return None


def _ocr_items(engine, gray_image):
    """[(x0, y0, x1, y1, text, score), ...] for one greyscale PIL image."""

    output = engine(np.asarray(gray_image.convert("RGB")))
    boxes = getattr(output, "boxes", None)
    texts = getattr(output, "txts", None) or ()
    scores = getattr(output, "scores", None) or ()

    if boxes is None or not texts:
        return []

    items = []

    for box, text, score in zip(boxes, texts, scores):
        xs = [point[0] for point in box]
        ys = [point[1] for point in box]
        items.append((min(xs), min(ys), max(xs), max(ys), str(text), float(score)))

    return items


def _items_to_lines(items, page_width):
    """Groups OCR boxes into text lines in reading order (handles 2 columns)."""

    if not items:
        return []

    middle = page_width / 2
    left = [item for item in items if item[2] < middle + page_width * 0.02]
    right = [item for item in items if item[0] > middle - page_width * 0.02]
    spanning = [item for item in items if item not in left and item not in right]
    two_columns = len(left) >= 4 and len(right) >= 4 and len(spanning) <= 0.1 * len(items)
    columns = [left, [item for item in right if item not in left]] if two_columns else [items]
    lines = []

    for column in columns:
        rows = []

        for item in sorted(column, key=lambda it: (it[1] + it[3]) / 2):
            centre = (item[1] + item[3]) / 2
            height = item[3] - item[1]

            for row in rows:
                if abs(row["centre"] - centre) < 0.6 * min(height, row["height"]):
                    row["items"].append(item)
                    break
            else:
                rows.append({"centre": centre, "height": height, "items": [item]})

        for row in sorted(rows, key=lambda r: r["centre"]):
            parts = sorted(row["items"], key=lambda it: it[0])
            lines.append("   ".join(part[4] for part in parts))

    return lines


def ocr_image_to_text(image_bytes):
    """
    Reads an image with the built-in OCR. Returns (text, error). Lines
    that look like formulas are re-read at higher zoom and their minus
    signs merged (see _merge_minus_signs); flattened dimensional
    formulas get their exponents back.
    """

    engine = get_ocr_engine()

    if engine is None:
        return "", (
            "The built-in OCR engine isn't installed on this server "
            "(package 'rapidocr' + 'onnxruntime'). Use the AI method "
            "or ask the app admin to redeploy with the updated "
            "requirements.txt."
        )

    from PIL import Image, ImageFilter, ImageOps

    try:
        prepared, _ = prepare_image_for_vision(image_bytes)
        base = Image.open(io.BytesIO(prepared)).convert("L")
    except Exception as error:
        return "", f"Couldn't open the image: {error}"

    if np.asarray(base).mean() < 128:
        base = ImageOps.invert(base)  # light text on dark -> dark on light

    first_scale = 2.0 if max(base.size) <= 1600 else 1.0

    def read_at(scale, bold=False):
        size = (max(1, int(base.width * scale)), max(1, int(base.height * scale)))
        image = base if scale == 1.0 else base.resize(size, Image.LANCZOS)

        if bold:
            # Thickens strokes so hairline minus signs survive detection.
            image = image.filter(ImageFilter.MinFilter(3))

        # Boxes back in base-image coordinates so passes can be compared.
        return [
            (x0 / scale, y0 / scale, x1 / scale, y1 / scale, text, score)
            for x0, y0, x1, y1, text, score in _ocr_items(engine, image)
        ]

    try:
        primary = read_at(first_scale)
    except Exception as error:
        return "", f"OCR failed: {error}"

    # Thin minus signs in small exponents are the classic OCR miss, and
    # which ones get missed depends on zoom and stroke weight. When the
    # page has formula-like text, read it again at other zooms (plain and
    # with thickened strokes) and keep every minus sign any reading saw
    # (see _merge_minus_signs).
    extra_passes = []

    if any(_FORMULA_HINT_RE.search(item[4]) for item in primary):
        passes = (
            (first_scale * 1.5, False),
            (first_scale * 2.0, False),
            (1.0, True),
            (first_scale, True),
            (4.0, True),
        )

        for scale, bold in passes:
            if max(base.size) * scale > OCR_MAX_PASS_SIDE_PX:
                continue

            try:
                extra_passes.append(read_at(scale, bold))
            except Exception:
                continue

    def same_box(first, second):
        overlap_y = min(first[3], second[3]) - max(first[1], second[1])
        overlap_x = min(first[2], second[2]) - max(first[0], second[0])
        height = min(first[3] - first[1], second[3] - second[1])
        width = min(first[2] - first[0], second[2] - second[0])
        return overlap_y > 0.5 * height and overlap_x > 0.5 * width

    refined = []

    for item in primary:
        text = item[4]

        if extra_passes and _FORMULA_HINT_RE.search(text):
            variants = [text]

            for reading in extra_passes:
                matches = [other for other in reading if same_box(item, other)]

                if len(matches) == 1:
                    variants.append(matches[0][4])

            text = _merge_minus_signs(variants)

        refined.append(item[:4] + (restore_dimension_exponents(text), item[5]))

    lines = _items_to_lines(refined, base.width)

    return "\n".join(lines), None


def pdf_page_text_with_scripts(pdf_bytes, page_number):
    """
    Text of one PDF page from its text layer, keeping superscripts and
    subscripts as ^{...} / _{...} (a plain text dump would turn
    'T⁻³' into 'T-3').
    """

    if fitz is None:
        return ""

    document = fitz.open(stream=pdf_bytes, filetype="pdf")

    try:
        page = document.load_page(page_number - 1)
        lines_out = []

        for block in page.get_text("dict").get("blocks", []):
            if block.get("type") != 0:
                continue

            for line in block.get("lines", []):
                spans = [span for span in line.get("spans", []) if span.get("text")]

                if not spans:
                    continue

                base_size = max(span["size"] for span in spans)
                baselines = [span["origin"][1] for span in spans if span["size"] >= base_size * 0.95]
                baseline = max(baselines) if baselines else spans[0]["origin"][1]
                parts = []

                for span in spans:
                    text = span["text"]

                    if not text.strip():
                        parts.append(text)
                        continue

                    small = span["size"] < base_size * 0.85
                    raised = span["origin"][1] < baseline - base_size * 0.15
                    lowered = span["origin"][1] > baseline + base_size * 0.08

                    if (span.get("flags", 0) & 1) or (small and raised):
                        parts.append("^{" + text.strip() + "}")
                    elif small and lowered:
                        parts.append("_{" + text.strip() + "}")
                    else:
                        parts.append(text)

                lines_out.append("".join(parts))

        return "\n".join(lines_out)
    finally:
        document.close()


EXTRACTION_METHODS = {
    "Built-in OCR — no AI needed (free)": "ocr",
    "AI vision model (needs a vision-capable model)": "ai",
}


def read_questions_without_ai(page):
    """
    One page -> (raw_questions, text_read, error) using only the PDF's
    text layer or the built-in OCR, then the rule-based question reader.
    """

    if page.get("mode") == "text":
        text = ""

        if page.get("pdf_bytes") is not None:
            try:
                text = pdf_page_text_with_scripts(page["pdf_bytes"], page["page_number"])
            except Exception:
                text = ""

        text = restore_dimension_exponents(text or page.get("page_text") or "")
    else:
        text, error = ocr_image_to_text(page.get("image_bytes"))

        if error:
            return [], "", error

    return parse_questions_from_text(text), text, None


def parse_questions_from_text(text):
    """
    Rule-based reader: plain question-paper text -> list of
    {"question", "options", "key", "explanation"} dicts. Never invents
    content; anything it can't place stays with the nearest question
    so the lecturer can fix it in the review step.
    """

    questions = []
    current = None
    mode = "question"  # "question" | "explanation"
    in_answer_key = False
    answer_key = {}

    def start_question(number, body):
        nonlocal current, mode
        current = {
            "number": number,
            "question": body.strip(),
            "options": [],
            "option_style": None,
            "key": None,
            "explanation": "",
        }
        questions.append(current)
        mode = "question"

    def next_option_index():
        return len(current["options"]) + 1

    def add_option(label, body):
        if current["option_style"] is None:
            current["option_style"] = _option_style(label)

        current["options"].append(body.strip())

    for raw_line in str(text or "").splitlines():
        line = re.sub(r"\s+", " ", raw_line).strip()

        if not line:
            continue

        if _ANSWER_KEY_HEADER_RE.match(line):
            in_answer_key = True
            continue

        if in_answer_key:
            for number, label in _ANSWER_KEY_PAIR_RE.findall(line):
                answer_key[int(number)] = label
            continue

        answer = _ANSWER_LINE_RE.match(line)

        if answer and current is not None:
            current["key"] = answer.group(1)
            rest = line[answer.end():].strip(" :.-")

            if rest:
                current["explanation"] += (" " if current["explanation"] else "") + rest

            continue

        solution = _SOLUTION_LINE_RE.match(line)

        if solution and current is not None:
            mode = "explanation"
            current["explanation"] += (" " if current["explanation"] else "") + solution.group(1).strip()
            continue

        prefixed = _PREFIXED_QUESTION_RE.match(line)

        if prefixed:
            start_question(int(prefixed.group(1)), prefixed.group(2))
            continue

        if current is not None and mode == "question":
            inline = _split_inline_options(line)

            if inline and _option_index(inline[0][0]) == next_option_index():
                for label, body in inline:
                    add_option(label, body)
                continue

            option = _OPTION_LINE_RE.match(line)

            if option:
                label = option.group(1) or option.group(2) or option.group(3)
                style_ok = (
                    current["option_style"] is None
                    or current["option_style"] == _option_style(label)
                )

                if _option_index(label) == next_option_index() and style_ok and next_option_index() <= 6:
                    add_option(label, option.group(4))
                    continue

        numbered = _NUMBERED_LINE_RE.match(line)

        if numbered:
            start_question(int(numbered.group(1)), numbered.group(2))
            continue

        if current is None:
            continue  # heading / instructions before the first question

        if mode == "explanation":
            current["explanation"] += " " + line
        elif current["options"]:
            current["options"][-1] += " " + line
        else:
            current["question"] += (" " if current["question"] else "") + line

    results = []

    for position, item in enumerate(questions, start=1):
        key = item["key"] or answer_key.get(item["number"]) or answer_key.get(position)

        if not item["question"] and not item["options"]:
            continue

        results.append(
            {
                "question": item["question"],
                "options": item["options"],
                "key": key,
                "explanation": item["explanation"].strip() or None,
            }
        )

    return results


def build_extraction_user_prompt(page_label, page_text=None):
    if page_text is not None:
        return f"""This is the extracted text of: {page_label}.
Transcribe every question in it following the schema exactly. Return
JSON only.

SOURCE TEXT:
---
{page_text}
---"""

    return (
        f"This image is: {page_label}.\n"
        "Transcribe every question on it following the schema exactly. "
        "Return JSON only."
    )


# ---------------------------------------------------------------------------
# OMNIROUTE CALLS AND VALIDATION
# ---------------------------------------------------------------------------
def is_retryable_error(error):
    text = str(error).upper()

    return any(
        code in text
        for code in [
            "429",
            "500",
            "502",
            "503",
            "504",
            "TIMEOUT",
            "UNAVAILABLE",
            "RESOURCE_EXHAUSTED",
            "RATE LIMIT",
            "OVERLOADED",
            "EMPTY RESPONSE",
            # Connection-level failures — the openai SDK's
            # APIConnectionError renders as the bare string
            # "Connection error." with no code attached, which none
            # of the codes above would match. This is the common
            # failure mode for a local OmniRoute proxy that's
            # crashed, restarted, or gotten overloaded mid-run —
            # exactly the kind of thing worth retrying, since the
            # proxy may well recover a few seconds later.
            "CONNECTION ERROR",
            "CONNECTION REFUSED",
            "CONNECTION RESET",
            "CONNECTION ABORTED",
            "REMOTE END CLOSED",
            "BROKEN PIPE",
            "NEWCONNECTIONERROR",
            "MAX RETRIES EXCEEDED",
            "NAME OR SERVICE NOT KNOWN",
            "TEMPORARY FAILURE IN NAME RESOLUTION",
        ]
    )


def estimate_max_tokens(number_of_questions):
    """
    Sizes the response token budget to the number of questions
    requested for THIS page, instead of one fixed value for every
    page regardless of how much was asked for. A too-small budget is
    exactly what causes the model's JSON to be cut off mid-generation
    (invalid/truncated JSON — "Unterminated string...") and the whole
    page failing outright, even for pages that only needed a couple
    of questions' worth of headroom more than they got.
    """

    return max(
        MIN_RESPONSE_TOKENS,
        min(
            MAX_RESPONSE_TOKENS,
            RESPONSE_TOKEN_OVERHEAD
            + number_of_questions * TOKENS_PER_QUESTION_ESTIMATE,
        ),
    )


def salvage_partial_questions(raw):
    """
    Best-effort recovery when the model's JSON was cut off mid-
    generation. Scans the "questions" array character-by-character
    (respecting string escaping, so braces inside an explanation's
    text don't confuse the scan) and keeps every individually-
    parseable {...} object it finds, discarding only the trailing
    incomplete one. Returns [] if nothing usable is found — that's
    fine, the caller treats an empty salvage the same as a hard
    failure for that attempt.
    """

    text = extract_json_object(raw)
    start = text.find("[")

    if start < 0:
        return []

    depth = 0
    obj_start = None
    in_string = False
    escape = False
    salvaged = []

    for index in range(start, len(text)):
        char = text[index]

        if in_string:
            if escape:
                escape = False
            elif char == "\\":
                escape = True
            elif char == '"':
                in_string = False
            continue

        if char == '"':
            in_string = True
            continue

        if char == "{":
            if depth == 0:
                obj_start = index
            depth += 1
        elif char == "}":
            depth -= 1

            if depth == 0 and obj_start is not None:
                candidate = text[obj_start:index + 1]

                try:
                    salvaged.append(json.loads(candidate))
                except json.JSONDecodeError:
                    pass

                obj_start = None

    return salvaged


class HTMLResponseError(RuntimeError):
    """
    Raised when the provider returns an HTML web page instead of a
    JSON API response — this happens when the configured base URL
    points at a web page (a dashboard, a login screen, a 404 page)
    rather than the actual API endpoint. Retrying does nothing for
    this — every attempt will get the same HTML page back — and it
    will keep happening for every subsequent page too, so this is
    treated differently from ordinary transient failures: no
    escalating-token-budget retries, and the whole run stops rather
    than burning through every remaining page repeating the mistake.
    """


def looks_like_html_response(raw):
    stripped = (raw or "").strip().lower()
    return stripped.startswith("<!doctype") or stripped.startswith(
        "<html"
    )


def extract_json_object(raw):
    raw = (raw or "").strip()

    raw = re.sub(
        r"^```(?:json)?\s*",
        "",
        raw,
        flags=re.IGNORECASE,
    )

    raw = re.sub(r"\s*```$", "", raw)

    start = raw.find("{")
    end = raw.rfind("}")

    if start >= 0 and end > start:
        return raw[start:end + 1]

    return raw


def fetch_agentrouter_models(api_key):
    """
    Fetches the list of model IDs Agent Router currently exposes via
    its OpenAI-compatible GET /v1/models endpoint, so the sidebar can
    offer a live dropdown instead of a free-text field. Raises on
    failure (bad key, network error, or an upstream that doesn't
    support model listing) — callers should catch this and fall back
    to manual model-ID entry.
    """

    client = OpenAI(
        api_key=api_key,
        base_url=AGENTROUTER_BASE_URL,
        default_headers=AGENTROUTER_CLIENT_HEADERS,
    )
    response = client.models.list()

    model_ids = sorted({model.id for model in response.data if model.id})

    if not model_ids:
        raise RuntimeError("Agent Router returned an empty model list.")

    return model_ids


def fetch_claude_models(api_key):
    """
    Fetches the list of model IDs available on the Claude (Anthropic)
    API via its native GET /v1/models endpoint. Raises on failure —
    callers should catch this and fall back to manual model-ID entry,
    same as fetch_agentrouter_models.
    """

    if anthropic is None:
        raise RuntimeError(
            "The 'anthropic' package isn't installed "
            "(pip install anthropic)."
        )

    client = anthropic.Anthropic(api_key=api_key)
    response = client.models.list()

    model_ids = sorted(
        {
            model.id
            for model in response.data
            if getattr(model, "id", None)
        }
    )

    if not model_ids:
        raise RuntimeError("Claude API returned an empty model list.")

    return model_ids


class ProviderTimeoutError(RuntimeError):
    """The AI provider didn't reply within the time limit, even after a retry."""


def is_timeout_error(error):
    text = f"{type(error).__name__} {error}".lower()
    return "timeout" in text or "timed out" in text


def _client_read_timeout(client):
    timeout = getattr(client, "timeout", None)
    seconds = getattr(timeout, "read", timeout)

    try:
        return int(float(seconds))
    except (TypeError, ValueError):
        return None


_IMAGE_UNSUPPORTED_HINTS = (
    "image", "vision", "multimodal", "multi-modal", "image_url",
    "content type", "content_type", "unsupported content",
)


def explain_provider_error(error, sent_images=False):
    """A plain-language explanation of a failed AI request."""

    message = str(error)

    if isinstance(error, ProviderTimeoutError):
        return message

    lowered = message.lower()

    if sent_images and any(hint in lowered for hint in _IMAGE_UNSUPPORTED_HINTS):
        return (
            "The selected model can't read images, so it can't read this "
            "page. Choose a vision-capable model (for example a recent "
            "Claude, GPT-4o/4.1 or Gemini model) in the sidebar and try "
            f"again. Provider message: {message[:300]}"
        )

    return message[:600]


def build_client(provider, api_key, base_url=None, timeout_seconds=GENERATION_TIMEOUT_SECONDS):
    """
    Constructs the right SDK client for whichever provider is
    currently selected. OmniRoute and Agent Router are both
    OpenAI-compatible (just different base URLs / headers); Claude
    API uses Anthropic's own SDK and Messages API shape, handled
    separately in call_chat_completion_api.
    """

    if provider == "Claude API":
        if anthropic is None:
            raise RuntimeError(
                "The 'anthropic' package isn't installed. Run "
                "`pip install anthropic` and restart the app."
            )

        # max_retries=0: retries are handled (visibly) by
        # call_chat_completion_api, not silently inside the SDK.
        return anthropic.Anthropic(
            api_key=api_key,
            timeout=anthropic.Timeout(timeout_seconds, connect=REQUEST_CONNECT_TIMEOUT_SECONDS),
            max_retries=0,
        )

    timeout = openai.Timeout(timeout_seconds, connect=REQUEST_CONNECT_TIMEOUT_SECONDS)

    if provider == "Agent Router":
        return OpenAI(
            api_key=api_key,
            base_url=AGENTROUTER_BASE_URL,
            default_headers=AGENTROUTER_CLIENT_HEADERS,
            timeout=timeout,
            max_retries=0,
        )

    # OmniRoute (or any other self-hosted OpenAI-compatible endpoint)
    return OpenAI(api_key=api_key, base_url=base_url, timeout=timeout, max_retries=0)


def render_model_dropdown_ui(session_prefix, fetch_fn, api_key_stripped, provider_label):
    """
    Renders a live-fetched model dropdown with a manual-entry
    fallback, reused by both Agent Router and Claude API in the
    sidebar (OmniRoute stays manual-entry-only since it's a flexible
    local proxy). session_prefix keeps each provider's cached model
    list independent in session_state, so switching providers doesn't
    clobber another provider's fetched list. Returns the selected or
    manually-typed model ID string.
    """

    models_key = f"{session_prefix}_models"
    hash_key = f"{session_prefix}_models_key_hash"
    error_key = f"{session_prefix}_models_error"

    if models_key not in st.session_state:
        st.session_state[models_key] = []
    if hash_key not in st.session_state:
        st.session_state[hash_key] = None
    if error_key not in st.session_state:
        st.session_state[error_key] = None

    key_hash = (
        hashlib.sha256(api_key_stripped.encode()).hexdigest()
        if api_key_stripped
        else None
    )

    refresh_clicked = st.button(
        "🔄 Refresh model list",
        width="stretch",
        disabled=not api_key_stripped,
        key=f"{session_prefix}_refresh_button",
        help=f"Re-fetch the list of models {provider_label} currently offers.",
    )

    should_fetch = api_key_stripped and (
        refresh_clicked
        or st.session_state[hash_key] != key_hash
    )

    if should_fetch:
        with st.spinner(f"Fetching available models from {provider_label}..."):
            try:
                st.session_state[models_key] = fetch_fn(api_key_stripped)
                st.session_state[error_key] = None
            except Exception as error:
                st.session_state[models_key] = []
                st.session_state[error_key] = str(error)

        st.session_state[hash_key] = key_hash

    elif not api_key_stripped:
        # Key was cleared — drop any stale list from a previous key.
        st.session_state[models_key] = []
        st.session_state[hash_key] = None
        st.session_state[error_key] = None

    available_models = st.session_state[models_key]

    if available_models:
        return st.selectbox(
            "Model ID",
            options=available_models,
            key=f"{session_prefix}_model_select",
            help=f"Fetched live from {provider_label}'s model list.",
        )

    if st.session_state[error_key]:
        st.warning(
            "Couldn't load the model list "
            f"({st.session_state[error_key]}). "
            "Enter a model ID manually below."
        )
    elif not api_key_stripped:
        st.caption(
            "Enter your API key above to load the model dropdown."
        )

    return st.text_input(
        "Model ID (manual entry)",
        value=DEFAULT_MODEL,
        key=f"{session_prefix}_model_manual",
    )


def call_chat_completion_api(
    provider,
    client,
    model,
    system_prompt,
    user_prompt,
    max_tokens,
    image_png_bytes=None,
    image_mime="image/png",
    images=None,
):
    """
    image_png_bytes is optional and only used by extract-mode (source-
    paper transcription), which needs the model to actually see the
    page rather than work from extracted text. Every other call site
    passes no image, so this is purely additive — the request shape
    for the existing text-only generation flow is unchanged.
    """

    last_error = None
    timeouts = 0
    # images: optional list of (bytes, mime) sent in order after the
    # text; image_png_bytes/image_mime is the single-image shorthand.
    attachments = list(images or [])

    if image_png_bytes:
        attachments.insert(0, (image_png_bytes, image_mime))

    encoded = [
        (base64.b64encode(data).decode("ascii"), mime)
        for data, mime in attachments
        if data
    ]

    for attempt in range(MAX_API_ATTEMPTS):
        try:
            finish_reason = None

            if provider == "Claude API":
                if encoded:
                    user_content = [
                        {
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": mime,
                                "data": data,
                            },
                        }
                        for data, mime in encoded
                    ] + [{"type": "text", "text": user_prompt}]
                else:
                    user_content = user_prompt

                response = client.messages.create(
                    model=model,
                    system=system_prompt,
                    messages=[
                        {"role": "user", "content": user_content}
                    ],
                    max_tokens=max_tokens,
                )

                content = "".join(
                    getattr(block, "text", "")
                    for block in response.content
                    if getattr(block, "type", None) == "text"
                )

                finish_reason = getattr(response, "stop_reason", None)

            else:
                # OmniRoute and Agent Router are both OpenAI-compatible.
                if encoded:
                    user_content = [{"type": "text", "text": user_prompt}] + [
                        {
                            "type": "image_url",
                            "image_url": {"url": f"data:{mime};base64,{data}"},
                        }
                        for data, mime in encoded
                    ]
                else:
                    user_content = user_prompt

                request = {
                    "model": model,
                    "messages": [
                        {
                            "role": "system",
                            "content": system_prompt,
                        },
                        {
                            "role": "user",
                            "content": user_content,
                        },
                    ],
                    "temperature": 0.2,
                    "max_tokens": max_tokens,
                }

                try:
                    response = client.chat.completions.create(
                        **request,
                        response_format={
                            "type": "json_object"
                        },
                    )
                except Exception as format_error:
                    if "response_format" not in str(
                        format_error
                    ).lower():
                        raise

                    response = client.chat.completions.create(
                        **request
                    )

                # Defensive handling of the response shape: most
                # OpenAI-compatible proxies return the standard
                # ChatCompletion object with a `.choices` list, but
                # some (a known quirk with certain self-hosted
                # gateways, including OmniRoute in some configs) hand
                # back the raw completion text directly as a plain
                # string instead of the full envelope. Treat that as
                # the content itself rather than crashing with
                # "'str' object has no attribute 'choices'" — and for
                # any OTHER unexpected shape, raise a clear,
                # diagnosable error instead of a bare AttributeError.
                if isinstance(response, str):
                    content = response
                    finish_reason = None
                else:
                    choices = getattr(response, "choices", None) or []

                    if not choices:
                        raise RuntimeError(
                            "The provider returned a response with "
                            "no `choices` (response type: "
                            f"{type(response).__name__}). This "
                            "usually means the proxy or model "
                            "doesn't fully implement the standard "
                            "OpenAI chat-completions response shape."
                        )

                    content = choices[0].message.content
                    finish_reason = getattr(
                        choices[0], "finish_reason", None
                    )

            if not content:
                # finish_reason tells us WHY it came back empty —
                # content_filter (upstream safety block), length (ran
                # out of tokens, e.g. a reasoning model spending its
                # whole budget on hidden reasoning), or something
                # else. Surfacing it here means the next occurrence
                # is diagnosable from the on-screen error instead of
                # just "empty response" with no clue why.
                raise RuntimeError(
                    "The model returned an empty response "
                    f"(finish_reason={finish_reason}). This is "
                    "treated as retryable — a transient provider "
                    "hiccup is the most common cause."
                )

            return content

        except Exception as error:
            last_error = error

            if is_timeout_error(error):
                timeouts += 1
                limit = _client_read_timeout(client)
                waited = f"{limit} seconds" if limit else "the time limit"

                if timeouts > MAX_TIMEOUT_RETRIES or attempt == MAX_API_ATTEMPTS - 1:
                    raise ProviderTimeoutError(
                        f"The AI provider didn't reply within {waited} "
                        f"(tried {timeouts} times), so the request was "
                        "stopped instead of waiting indefinitely. Most "
                        "common causes: the selected model can't read "
                        "images (pick a vision-capable model), the model "
                        "or proxy is overloaded, or the provider is "
                        "down. Try a different model, or try again in a "
                        "few minutes."
                    ) from error

                st.info(
                    f"No reply from the AI after {waited} — retrying "
                    "once more before giving up."
                )
                continue

            if (
                not is_retryable_error(error)
                or attempt == MAX_API_ATTEMPTS - 1
            ):
                raise

            delay = min(
                60,
                (2 ** attempt) * 8 + random.uniform(0, 3),
            )

            st.info(
                f"Temporary provider error. Retrying in "
                f"{delay:.0f} seconds "
                f"(attempt {attempt + 1}/"
                f"{MAX_API_ATTEMPTS - 1})."
            )

            time.sleep(delay)

    raise last_error


def resolve_key(question):
    options = question.get("options", [])
    key = str(question.get("key", "")).strip()

    if key in {"1", "2", "3", "4"}:
        return key

    for index, option in enumerate(options, start=1):
        if str(option).strip() == key:
            return str(index)

    return None


def extract_questions_from_page(
    provider,
    client,
    model,
    page_label,
    image_png_bytes=None,
    image_mime="image/png",
    page_text=None,
):
    """
    Extract-mode counterpart to generate_questions_for_page: instead of
    asking the model to invent questions from source text, this asks
    the model to transcribe whatever questions (and, if visible,
    answers) are already present in the page — as plain extracted
    TEXT whenever the PDF has a real text layer (cheaper, faster, and
    far more reliable than vision — works with any text-capable
    model, not just vision-capable ones), falling back to the
    rendered page IMAGE only when there's no text to work from (a
    scanned page, or a raw image upload). Exactly one of
    image_png_bytes/page_text is expected to be set. Reuses the same
    JSON-recovery machinery (extract_json_object,
    salvage_partial_questions) since the response shape is the same
    {"questions": [...]} envelope either way.
    """

    user_prompt = build_extraction_user_prompt(page_label, page_text)
    max_tokens = EXTRACTION_RESPONSE_TOKENS
    data = None
    raw = ""
    last_json_error = None

    for json_attempt in range(MAX_JSON_RETRY_ATTEMPTS):
        raw = call_chat_completion_api(
            provider,
            client,
            model,
            EXTRACTION_SYSTEM_PROMPT,
            user_prompt,
            max_tokens,
            image_png_bytes=image_png_bytes,
            image_mime=image_mime,
        )

        if looks_like_html_response(raw):
            raise HTMLResponseError(
                "The provider returned an HTML web page instead of a "
                "JSON API response. This almost always means the "
                "configured base URL points at a web page rather than "
                "the actual API endpoint — double-check the base URL "
                f"in the sidebar. Response preview: {raw[:200]!r}"
            )

        try:
            data = json.loads(extract_json_object(raw))
            break
        except json.JSONDecodeError as error:
            last_json_error = error
            salvaged_now = salvage_partial_questions(raw)

            if salvaged_now:
                data = {"questions": salvaged_now}
                break

            max_tokens = min(MAX_RESPONSE_TOKENS, int(max_tokens * 1.6))

            if json_attempt < MAX_JSON_RETRY_ATTEMPTS - 1:
                st.info(
                    f"The model's JSON for {page_label} looked "
                    "truncated — retrying "
                    f"(attempt {json_attempt + 2}/"
                    f"{MAX_JSON_RETRY_ATTEMPTS})."
                )
                time.sleep(2)

    if data is None:
        salvaged = salvage_partial_questions(raw)

        if salvaged:
            data = {"questions": salvaged}
        else:
            raise RuntimeError(
                f"Invalid JSON returned while extracting {page_label} "
                f"after {MAX_JSON_RETRY_ATTEMPTS} attempts: "
                f"{last_json_error}. Preview: {raw[:350]!r}"
            )

    questions = data.get("questions", [])

    return questions if isinstance(questions, list) else []


def resolve_extracted_key(options, raw_key):
    """
    Extract-mode's answer might be printed on the source as a number
    ("1"-"4"), a letter ("A"-"D"), or the option's own text — unlike
    generation mode, where the model always returns a plain "1"-"4".
    Returns None (caller treats this as "missing") when nothing
    matches, rather than guessing.
    """

    if raw_key is None:
        return None

    key = str(raw_key).strip()

    if not key:
        return None

    if key in {"1", "2", "3", "4"}:
        return key

    letter_map = {"A": "1", "B": "2", "C": "3", "D": "4"}

    if key.upper() in letter_map:
        return letter_map[key.upper()]

    for index, option in enumerate(options, start=1):
        if str(option).strip().lower() == key.lower():
            return str(index)

    return None


def normalize_extracted_question(raw, difficulty, bloom_level):
    """
    Extract-mode counterpart to validate_question: cleans a single
    transcribed item into the same shape add_question_table expects.
    Unlike generation mode, this never shuffles option order or
    second-guesses the content — these are real, already-printed
    questions, so fidelity to the source matters more than any
    automated quality check. The only thing that can block use is a
    missing answer key, which is surfaced as a review flag (and
    handled by the missing-answer dialog before DOCX export).
    """

    if not isinstance(raw, dict):
        return None, "Item is not an object — nothing to include."

    text = sanitize_math_text(raw.get("question", ""))

    if not text:
        return None, "Question text is empty — nothing to include."

    review_flags = []

    raw_options = raw.get("options", [])

    if not isinstance(raw_options, list):
        raw_options = []

    options = [
        sanitize_math_text(option)
        for option in raw_options
        if str(option).strip()
    ]

    explanation = sanitize_math_text(raw.get("explanation") or "")

    if options:
        question_type = "MCQ"

        if len(options) < 4:
            review_flags.append(
                f"Only {len(options)} option(s) were found on the "
                "source — padded with blanks; check nothing was "
                "missed."
            )
            options = options + [""] * (4 - len(options))
        elif len(options) > 4:
            review_flags.append(
                f"{len(options)} options were found on the source — "
                "trimmed to 4; verify nothing important was cut."
            )
            options = options[:4]

        key = resolve_extracted_key(options, raw.get("key"))
    else:
        question_type = "Numerical"
        key = str(raw.get("key") or "").strip() or None

    if key is None:
        review_flags.append(
            "MISSING ANSWER KEY — the source did not show a visible "
            "answer for this question. Fill in the correct answer "
            "before use."
        )

    cleaned = {
        "question_type": question_type,
        "question": text,
        "options": options,
        "key": key or "",
        "difficulty": difficulty,
        "bloom_level": bloom_level,
        "explanation": explanation,
        "review_flags": review_flags,
    }

    return cleaned, ""


def validate_question(
    question,
    subject,
    exam_mode,
    question_type,
    previous_questions,
    previous_concepts,
    figures_by_id=None,
):
    """
    Cleans and normalizes a model-generated question for the Word
    document. This is intentionally NOT a gate that drops questions
    for quality/duplication concerns — a human subject lecturer
    reviews every generated question before use, so silently
    discarding content the model already spent tokens producing does
    more harm (losing usable questions) than good. Instead, every
    concern that used to cause a hard rejection is now recorded as a
    "review flag" and written into the document's #Review Notes*
    field, so the lecturer can jump straight to whatever needs a
    second look instead of hunting through 60 questions blind.

    The only two things that still cause a question to be dropped
    entirely are (1) the item isn't a parseable object at all, or
    (2) the question stem is completely empty — there is nothing a
    lecturer could review in either case.
    """

    if not isinstance(question, dict):
        return None, "Question is not an object — nothing to include."

    review_flags = []

    text = sanitize_math_text(
        question.get("question", "")
    )

    explanation = sanitize_math_text(
        question.get("explanation", "")
    )

    concept_tested = str(
        question.get("concept_tested", "")
    ).strip()

    concept_id = str(
        question.get("concept_id", "")
    ).strip().lower()

    concept_id = re.sub(r"[^a-z0-9]+", "_", concept_id).strip("_")

    if not concept_id and concept_tested:
        concept_id = slugify_concept(concept_tested)

    # Textbook figure numbers ("Figure 7.1", "Fig. 7.4(a)") never reach
    # the question bank.
    had_figure_number = bool(_FIGURE_REFERENCE_RE.search(text + " " + explanation))
    text = neutralize_figure_references(text)
    explanation = neutralize_figure_references(explanation)

    if _TEXTBOOK_REFERENCE_RE.search(text):
        review_flags.append(
            "Question text refers to the textbook/source — reword it so it "
            "stands on its own."
        )

    # The only image a question ever gets is the real source figure
    # the lecturer selected and the model tied to this question by its
    # id (F1, F2, ...). Nothing is drawn or guessed.
    figures_by_id = figures_by_id or {}
    figure_id = str(question.get("figure_id") or "").strip().upper()
    figure = figures_by_id.get(figure_id) if figure_id else None

    if figure_id and figure is None:
        review_flags.append(
            f"The model referred to figure {figure_id!r}, which isn't one "
            "of the selected figures — no image was attached; check the "
            "question doesn't depend on a figure."
        )
        figure_id = ""

    if figure is not None and not _USES_FIGURE_RE.search(text):
        # Tied to a picture, but the question never uses it: the picture
        # would just be decoration. Keep the question as text-only; the
        # figure gets a proper picture-based question in the follow-up.
        figure = None
        figure_id = ""
        review_flags.append(
            "The AI attached a figure to this question but didn't frame "
            "the question from it — kept as a text-only question."
        )

    if figure is None and _USES_FIGURE_RE.search(text) and re.search(
        r"\b(?:figure|diagram|image|picture)\b", text, re.IGNORECASE
    ):
        review_flags.append(
            "Question mentions a figure/diagram but no figure is attached "
            "— reword it or add the figure before use."
            + (" (A textbook figure number was removed.)" if had_figure_number else "")
        )

    if not text:
        return None, "Question text is empty — nothing to include."

    if contains_generic_question(text):
        review_flags.append(
            "Reads like generic passage recall rather than a "
            "concept test — check it's not just paraphrasing a "
            "sentence from the source."
        )

    if is_duplicate_question(text, previous_questions):
        review_flags.append(
            "Wording is very close to an earlier question in this "
            "run — check for duplication before use."
        )

    if is_duplicate_concept(concept_id, concept_tested, previous_concepts):
        review_flags.append(
            "May test the same underlying concept as an earlier "
            "question in this run, just phrased differently."
        )

    fields_to_scan = [
        text,
        explanation,
        *(question.get("options", []) or []),
    ]

    if any(contains_unwanted_script(field) for field in fields_to_scan):
        review_flags.append(
            "Contains unexpected non-English characters — check "
            "formatting/encoding."
        )

    if not concept_tested:
        review_flags.append(
            "Model did not provide a concept description for this "
            "question."
        )

    if exam_mode != "Textbook Practice":
        if question.get("requires_reasoning") is not True:
            review_flags.append(
                "Model did not mark this as requiring genuine "
                "reasoning — check it isn't pure recall for a "
                "competitive-exam question."
            )

        if question.get("bloom_level") not in {
            "Understand",
            "Apply",
            "Analyze",
            "Evaluate",
        }:
            review_flags.append(
                "Cognitive level (Bloom's) wasn't clearly set for a "
                "competitive-exam question."
            )

    difficulty = question.get("difficulty", "Medium")

    if difficulty not in {"Easy", "Medium", "Hard"}:
        review_flags.append(
            f"Difficulty value {difficulty!r} wasn't recognized — "
            "defaulted to Medium."
        )
        difficulty = "Medium"

    if question_type == "MCQ":
        options = question.get("options", [])

        if not isinstance(options, list):
            options = []

        options = [
            neutralize_figure_references(sanitize_math_text(option))
            for option in options
        ]

        if len(options) < 4:
            review_flags.append(
                f"Only {len(options)} option(s) were provided — "
                "padded with blanks; fill in the missing option(s) "
                "before use."
            )
            options = options + [""] * (4 - len(options))
        elif len(options) > 4:
            review_flags.append(
                f"{len(options)} options were provided — extra "
                "option(s) trimmed to 4; verify nothing important "
                "was cut."
            )
            options = options[:4]

        if len(set(option.strip() for option in options)) < 4:
            review_flags.append(
                "Two or more options are identical or near-"
                "identical — check the distractors."
            )

        key = resolve_key(
            {
                "options": options,
                "key": question.get("key"),
            }
        )

        if key is None:
            review_flags.append(
                "Answer key could not be matched to an option — "
                "defaulted to option 1; VERIFY THE CORRECT ANSWER."
            )
            key = "1"

        if explanation_conflicts_with_key(explanation, key, options):
            review_flags.append(
                "Explanation may second-guess itself or argue for a "
                "different option than the stored answer key — "
                "VERIFY THE CORRECT ANSWER before use."
            )

        # Models have a well-documented bias toward placing the
        # correct answer in the first couple of option slots. Shuffle
        # the options here (after the explanation-conflict check,
        # which relies on the model's own original numbering) and
        # remap the key to match, so the correct answer lands in a
        # uniformly random position across a run instead of
        # clustering in options 1-2.
        original_correct_index = int(key) - 1
        shuffle_order = list(range(4))
        random.shuffle(shuffle_order)
        options = [options[i] for i in shuffle_order]
        key = str(shuffle_order.index(original_correct_index) + 1)

        cleaned = dict(question)
        cleaned.update(
            {
                "question_type": "MCQ",
                "question": text,
                "options": options,
                "key": key,
                "difficulty": difficulty,
                "explanation": explanation,
                "concept_id": concept_id,
                "concept_tested": concept_tested,
                "subject": subject,
                "exam_mode": exam_mode,
                "figure_id": figure_id,
                "figure": figure,
                "review_flags": review_flags,
            }
        )

        return cleaned, ""

    key = str(question.get("key", "")).strip()

    if not key:
        review_flags.append(
            "Numerical answer was empty — fill it in before use."
        )

    if any(
        re.search(pattern, explanation, re.IGNORECASE)
        for pattern in HEDGING_PATTERNS
    ):
        review_flags.append(
            "Explanation may second-guess itself rather than give a "
            "clean final justification — VERIFY before use."
        )

    cleaned = dict(question)
    cleaned.update(
        {
            "question_type": "Numerical",
            "question": text,
            "options": [],
            "key": key,
            "difficulty": difficulty,
            "explanation": explanation,
            "concept_id": concept_id,
            "concept_tested": concept_tested,
            "subject": subject,
            "exam_mode": exam_mode,
            "figure_id": figure_id,
            "figure": figure,
            "review_flags": review_flags,
        }
    )

    return cleaned, ""


def _request_question_json(
    provider,
    client,
    model,
    system_prompt,
    user_prompt,
    number_of_questions,
    images,
):
    """
    One model request for a page's questions, with the response budget
    sized to the number of questions, retried with a larger budget on
    truncated JSON, and finally salvaged for any complete question
    objects rather than failing the whole page.
    """

    max_tokens = estimate_max_tokens(number_of_questions)
    data = None
    raw = ""
    last_json_error = None

    for json_attempt in range(MAX_JSON_RETRY_ATTEMPTS):
        raw = call_chat_completion_api(
            provider,
            client,
            model,
            system_prompt,
            user_prompt,
            max_tokens,
            images=images,
        )

        if looks_like_html_response(raw):
            # Retrying gains nothing here — the endpoint is serving a
            # web page, not the API, and will keep doing so for every
            # request. Fail immediately with a diagnosis.
            raise HTMLResponseError(
                "The provider returned an HTML web page instead of a "
                "JSON API response. This almost always means the "
                "configured base URL points at a web page (a "
                "dashboard, a login screen, a 404 page) rather than "
                "the actual API endpoint — double-check the base URL "
                "in the sidebar. OpenAI-compatible API endpoints "
                "almost always end in /v1 (e.g. "
                "http://host:port/v1), not a page route like /home. "
                f"Response preview: {raw[:200]!r}"
            )

        try:
            data = json.loads(extract_json_object(raw))
            break
        except json.JSONDecodeError as error:
            last_json_error = error

            # A response truncated after most of the questions is
            # already good enough; retrying risks a worse truncation.
            salvaged_now = salvage_partial_questions(raw)
            good_enough = max(1, (number_of_questions + 1) // 2)

            if len(salvaged_now) >= good_enough:
                data = {"questions": salvaged_now}
                break

            max_tokens = min(MAX_RESPONSE_TOKENS, int(max_tokens * 1.8))

            if json_attempt < MAX_JSON_RETRY_ATTEMPTS - 1:
                st.info(
                    "The model's JSON looked truncated — retrying "
                    f"with a larger response budget "
                    f"(attempt {json_attempt + 2}/"
                    f"{MAX_JSON_RETRY_ATTEMPTS})."
                )
                time.sleep(2)

    if data is None:
        salvaged = salvage_partial_questions(raw)

        if not salvaged:
            raise RuntimeError(
                "Invalid JSON returned by model after "
                f"{MAX_JSON_RETRY_ATTEMPTS} attempts: "
                f"{last_json_error}. Preview: {raw[:350]!r}"
            )

        data = {"questions": salvaged}

    questions = data.get("questions", []) if isinstance(data, dict) else []

    return questions if isinstance(questions, list) else []


def _panel_meaning(caption, panel):
    """'(a) Squamous (b) Cuboidal', 'a' -> 'Squamous'."""

    if not caption or not panel:
        return ""

    match = re.search(
        r"\(\s*" + re.escape(panel) + r"\s*\)\s*([^()]+?)\s*(?=\(\s*[a-z]\s*\)|$)",
        caption,
        re.IGNORECASE,
    )
    return match.group(1).strip(" ,;:.") if match else ""


def describe_figures_for_prompt(figure_ids, figures_by_id, only_figures=False):
    """
    The SOURCE FIGURES block of the user prompt: what each picture shows
    (answer-key context — the student sees only the picture).
    """

    if not figure_ids:
        return ""

    lines = [
        "SOURCE FIGURES SELECTED FOR THIS PAGE (write at least one "
        "question for EACH, framed out of the picture, and set its "
        "\"figure_id\"). The descriptions are for you only:"
    ]

    for figure_id in figure_ids:
        figure = figures_by_id[figure_id]
        caption = figure.get("caption") or ""
        panel_meaning = _panel_meaning(caption, figure.get("panel"))
        whole = caption.split(":")[0].strip() if caption else ""
        shows = panel_meaning or caption or "(no caption in the source)"

        if panel_meaning and whole:
            shows = f"{panel_meaning} (one panel of: {whole})"

        parts = ", ".join(figure.get("parts") or []) or "(none named in the source)"
        markers = figure.get("markers") or []

        if markers:
            visible = "letters printed on the picture: " + ", ".join(
                f"{letter} = {name}" for letter, name in markers
            ) + " (the student sees only the letters)"
        else:
            visible = "no text at all is printed on the picture"

        lines.append(
            f"- {figure_id}: shows: {shows} | parts drawn: {parts} | {visible}"
        )

    if only_figures:
        lines.append(
            "EVERY question in this response must be framed out of one of "
            "the pictures above, one question per figure, each with its "
            "figure_id set."
        )

    return "\n".join(lines)


def generate_questions_for_page(
    provider,
    client,
    model,
    exam_mode,
    subject,
    topic,
    subtopic,
    page_text,
    number_of_questions,
    difficulty,
    question_type,
    figures,
    send_figure_images,
    previous_questions,
    previous_concepts,
):
    """
    Returns (valid_questions, rejected_reasons, missing_figure_ids).

    previous_questions and previous_concepts are the RUN-LEVEL lists
    (accumulated across every page processed so far, not just this
    page). They are mutated in place as questions are accepted, so
    duplicate/near-duplicate checking spans the whole run.

    figures are the real source figures the lecturer selected for this
    page. Each gets an id (F1, F2, ...) and MUST end up with at least
    one question: after the main request, any figure still without a
    question gets a dedicated follow-up request for just those
    figures. A figure is only reported missing if even that fails.
    """

    figures = list(figures or [])
    figure_ids = [f"F{index}" for index in range(1, len(figures) + 1)]
    figures_by_id = dict(zip(figure_ids, figures))
    number_of_questions = max(int(number_of_questions), len(figures))

    def images_for(ids):
        if not send_figure_images:
            return None

        return [
            (figures_by_id[figure_id]["image"], figures_by_id[figure_id]["mime"])
            for figure_id in ids
        ]

    valid = []
    rejected = []

    def accept(raw_questions):
        for question in raw_questions:
            cleaned, reason = validate_question(
                question,
                subject,
                exam_mode,
                question_type,
                previous_questions,
                previous_concepts,
                figures_by_id=figures_by_id,
            )

            if cleaned is None:
                rejected.append(reason)
                continue

            valid.append(cleaned)
            previous_questions.append(cleaned["question"])
            previous_concepts.append(
                {
                    "id": cleaned.get("concept_id", ""),
                    "text": cleaned.get("concept_tested", ""),
                }
            )

    system_prompt = build_generation_system_prompt(
        exam_mode,
        subject,
        question_type,
        figure_count=len(figures),
        figures_visible=bool(send_figure_images and figures),
    )

    user_prompt = build_generation_user_prompt(
        exam_mode,
        subject,
        topic,
        subtopic,
        page_text,
        number_of_questions,
        difficulty,
        question_type,
        describe_figures_for_prompt(figure_ids, figures_by_id),
        already_tested_concepts=previous_concepts,
    )

    accept(
        _request_question_json(
            provider,
            client,
            model,
            system_prompt,
            user_prompt,
            number_of_questions,
            images_for(figure_ids),
        )
    )

    covered = {question.get("figure_id") for question in valid}
    missing = [figure_id for figure_id in figure_ids if figure_id not in covered]

    if missing:
        # Follow-up request for just the figures that got no question,
        # so a selected figure is never silently left out.
        follow_up_system = build_generation_system_prompt(
            exam_mode,
            subject,
            question_type,
            figure_count=len(missing),
            figures_visible=bool(send_figure_images),
        )
        follow_up_user = build_generation_user_prompt(
            exam_mode,
            subject,
            topic,
            subtopic,
            page_text,
            len(missing),
            difficulty,
            question_type,
            describe_figures_for_prompt(missing, figures_by_id, only_figures=True),
            already_tested_concepts=previous_concepts,
        )

        try:
            time.sleep(MIN_REQUEST_DELAY)
            accept(
                _request_question_json(
                    provider,
                    client,
                    model,
                    follow_up_system,
                    follow_up_user,
                    len(missing),
                    images_for(missing),
                )
            )
        except HTMLResponseError:
            raise
        except Exception as error:
            rejected.append(f"Follow-up request for figures failed: {error}")

        covered = {question.get("figure_id") for question in valid}
        missing = [figure_id for figure_id in figure_ids if figure_id not in covered]

    return valid, rejected, missing


def final_review_pass(results):
    """
    Runs once, after every page has been generated, over the FULL
    flattened question bank. Unlike the old final_dedup_pass, this
    never removes a question — a subject lecturer reviews every
    generated question before use, so silently dropping one at the
    very last step is exactly the kind of thing that erodes trust in
    the tool. Instead, any question whose text or concept matches an
    earlier one ANYWHERE in the run (not just within its own page's
    live tracking) gets an extra review flag appended, so the
    lecturer sees it called out in #Review Notes* instead of it
    just vanishing.

    Returns (results, flagged_count) — results has the same
    questions in the same order, just with review_flags updated
    in place where applicable.
    """

    seen_questions = []
    seen_concepts = []
    flagged_count = 0

    for page_result in results:
        for question in page_result.get("questions", []):
            text = question.get("question", "")
            concept_id = question.get("concept_id", "")
            concept_text = question.get("concept_tested", "")

            is_dup_text = is_duplicate_question(text, seen_questions)
            is_dup_concept = is_duplicate_concept(
                concept_id, concept_text, seen_concepts,
            )

            if is_dup_text or is_dup_concept:
                flags = question.setdefault("review_flags", [])
                note = (
                    "Also matches another question elsewhere in "
                    "this run (cross-page check) — check for "
                    "duplication before use."
                )
                if note not in flags:
                    flags.append(note)
                flagged_count += 1

            seen_questions.append(text)
            seen_concepts.append(
                {"id": concept_id, "text": concept_text}
            )

    return results, flagged_count


# ---------------------------------------------------------------------------
# DOCX EXPORT
# ---------------------------------------------------------------------------
FIELD_LABELS = [
    "#Grade*",
    "#Subject*",
    "#Topic*",
    "#Sub-topic*",
    "#Question type*",
    "#Bloom's Taxonomy*",
    "#Question difficulty*",
    "#Question*",
    "#Option 1*",
    "#Option 2*",
    "#Option 3*",
    "#Option 4*",
    "#Key*",
    "#Explanation*",
    "#Source*",
    "#Remark*",
    "#Review Notes*",
]

NUMERICAL_OPTION_TEXT = (
    "N/A (Numerical answer type — no options)"
)


# The figure goes inside the question's value cell, which is about
# 3.2" wide in the 2-column question table; tall figures are capped by
# height so a single question never spills over a whole page.
FIGURE_DOCX_MAX_WIDTH_IN = 3.0
FIGURE_DOCX_MIN_WIDTH_IN = 1.6
FIGURE_DOCX_MAX_HEIGHT_IN = 3.2
FIGURE_DOCX_SCALE = 1.25  # slightly larger than printed size in the source


def figure_display_width(figure):
    width_in = figure.get("width_pt", 216) / 72 * FIGURE_DOCX_SCALE
    width_in = min(max(width_in, FIGURE_DOCX_MIN_WIDTH_IN), FIGURE_DOCX_MAX_WIDTH_IN)
    aspect = figure.get("height_pt", 1) / max(figure.get("width_pt", 1), 1)

    if width_in * aspect > FIGURE_DOCX_MAX_HEIGHT_IN:
        width_in = FIGURE_DOCX_MAX_HEIGHT_IN / aspect

    return Inches(max(width_in, 1.0))


def add_figure_to_cell(cell, figure):
    """Places the real source figure right after the question text."""

    paragraph = cell.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER

    try:
        paragraph.add_run().add_picture(
            io.BytesIO(figure["image"]),
            width=figure_display_width(figure),
        )
    except Exception:
        # Never let one bad image break the whole export.
        paragraph.add_run(
            "[Source figure could not be embedded — add it manually.]"
        ).italic = True


def add_question_table(
    document,
    grade,
    subject,
    topic,
    subtopic,
    question,
    source,
    remark,
):
    if question.get("question_type") == "Numerical":
        options = [NUMERICAL_OPTION_TEXT] * 4
    else:
        options = list(
            question.get("options")
            or ["", "", "", ""]
        )

        while len(options) < 4:
            options.append("")

    review_flags = question.get("review_flags") or []
    review_notes = (
        "; ".join(review_flags)
        if review_flags
        else "None — no automated concerns flagged."
    )

    values = [
        grade,
        subject,
        topic,
        subtopic,
        question.get("question_type", "MCQ"),
        question.get("bloom_level", ""),
        question.get("difficulty", ""),
        question.get("question", ""),
        options[0],
        options[1],
        options[2],
        options[3],
        question.get("key", ""),
        question.get("explanation", ""),
        source,
        remark,
        review_notes,
    ]

    table = document.add_table(
        rows=len(FIELD_LABELS),
        cols=2,
    )

    table.alignment = WD_TABLE_ALIGNMENT.CENTER

    for row_index, (label, value) in enumerate(
        zip(FIELD_LABELS, values)
    ):
        label_cell = table.cell(row_index, 0)
        value_cell = table.cell(row_index, 1)

        label_cell.text = ""
        value_cell.text = ""

        label_cell.paragraphs[0].add_run(label)

        add_math_runs(
            value_cell.paragraphs[0],
            value,
        )

        if label == "#Question*" and question.get("figure"):
            add_figure_to_cell(value_cell, question["figure"])

        set_light_border(label_cell)
        set_light_border(value_cell)

    document.add_paragraph("")


def enable_field_auto_update(document):
    """
    By default Word shows a field's cached fallback text (e.g. plain
    "3/4" or "√(41)") until the fields are manually refreshed (Ctrl+A,
    F9). Setting <w:updateFields w:val="true"/> in settings.xml makes
    Word recalculate — and properly render — every EQ field (our
    fraction and radical fields) automatically when the document is
    opened, so square roots show a real stretching radical bar and
    fractions render as stacked numerator/denominator without any
    manual step.
    """

    settings_element = document.settings.element
    update_fields = OxmlElement("w:updateFields")
    update_fields.set(qn("w:val"), "true")
    settings_element.append(update_fields)


def build_docx(
    results,
    grade,
    subject,
    topic,
    source_name,
):
    document = Document()
    enable_field_auto_update(document)

    for page_result in results:
        questions = page_result.get(
            "questions",
            [],
        )

        for question_number, question in enumerate(
            questions,
            start=1,
        ):
            add_question_table(
                document=document,
                grade=grade,
                subject=subject,
                topic=topic,
                subtopic=page_result["subtopic"],
                question=question,
                source=source_name,
                remark=(
                    f"Question {question_number} of "
                    f"{len(questions)} for selected page "
                    f"{page_result['page_number']}."
                    + (
                        " Includes the source figure from page "
                        f"{page_result['page_number']}."
                        if question.get("figure")
                        else ""
                    )
                ),
            )

    output = io.BytesIO()
    document.save(output)
    output.seek(0)

    return output


def build_docx_from_extracted(pages, grade, subject, topic, source_name):
    """
    Extract-mode counterpart to build_docx. pages is a list of
    {"label": str, "subtopic": str, "questions": [cleaned, ...]} —
    the same cleaned-question shape normalize_extracted_question
    produces, which add_question_table already knows how to render.
    """

    document = Document()
    enable_field_auto_update(document)

    for page in pages:
        questions = page.get("questions", [])

        for question_number, question in enumerate(questions, start=1):
            add_question_table(
                document=document,
                grade=grade,
                subject=subject,
                topic=topic,
                subtopic=page["subtopic"],
                question=question,
                source=source_name,
                remark=(
                    f"Extracted question {question_number} of "
                    f"{len(questions)} from {page['label']}."
                ),
            )

    output = io.BytesIO()
    document.save(output)
    output.seek(0)

    return output


# ---------------------------------------------------------------------------
# EXTRACT-MODE UI
# ---------------------------------------------------------------------------
def _finish_extraction_docx(pages, grade, subject, topic, source_name):
    total_questions = sum(len(page["questions"]) for page in pages)

    if total_questions == 0:
        st.error("No questions to include — nothing was extracted.")
        return

    document_buffer = build_docx_from_extracted(
        pages=pages,
        grade=grade,
        subject=subject,
        topic=topic,
        source_name=source_name,
    )

    safe_base_name = source_name.rsplit(".", 1)[0]

    # Same session_state contract the generation flow uses (see the
    # comment at its own st.session_state.generation_complete = True
    # further down) — this reuses that exact "results mode" screen,
    # since it's agnostic to how the DOCX bytes were produced.
    st.session_state.generation_complete = True
    st.session_state.generated_docx_bytes = document_buffer.getvalue()
    st.session_state.generated_filename = (
        f"Extracted_Question_Bank_{safe_base_name}.docx"
    )
    st.session_state.generated_total_questions = total_questions
    st.session_state.generated_page_count = len(pages)
    st.session_state.pop("ext_pending_build", None)
    st.rerun()


@st.dialog("Missing answer keys")
def show_missing_keys_dialog(missing_items, run_id):
    st.write(
        f"{len(missing_items)} question(s) have no visible answer on "
        "the source. Choose the correct answer for each below, or "
        "explicitly leave it blank to flag it for manual review "
        "instead."
    )

    for item in missing_items:
        item_id = item["item_id"]

        st.markdown(f"**{item['label']}** — {item['question'][:220]}")

        leave_blank = st.checkbox(
            "Leave blank for now (flagged for manual review in the "
            "document)",
            key=f"dlg_blank_{run_id}_{item_id}",
        )

        if not leave_blank:
            if item["question_type"] == "MCQ":
                labeled_options = [
                    f"{index + 1}. {option}"
                    if option.strip()
                    else f"{index + 1}. (blank)"
                    for index, option in enumerate(item["options"])
                ]
                st.selectbox(
                    "Correct option",
                    labeled_options,
                    key=f"dlg_answer_{run_id}_{item_id}",
                    index=None,
                    placeholder="Choose the correct option...",
                )
            else:
                st.text_input(
                    "Correct (numerical) answer",
                    key=f"dlg_answer_{run_id}_{item_id}",
                )

        st.markdown("---")

    dialog_cols = st.columns(2)

    with dialog_cols[0]:
        save_clicked = st.button(
            "Save and continue",
            type="primary",
            width="stretch",
        )

    with dialog_cols[1]:
        cancel_clicked = st.button(
            "Cancel (keep editing inline)",
            width="stretch",
        )

    if cancel_clicked:
        # Without an explicit way out, dismissing this dialog (ESC,
        # clicking outside) reruns the script with ext_pending_build
        # still set and nothing resolved — which would just reopen
        # the same dialog immediately. This gives an explicit escape
        # hatch back to the inline editor instead of a stuck modal.
        st.session_state.pop("ext_pending_build", None)
        st.rerun()

    if save_clicked:
        manual_keys = st.session_state.ext_manual_keys
        ack_blank = st.session_state.ext_ack_blank
        incomplete = False

        for item in missing_items:
            item_id = item["item_id"]
            blank_widget_key = f"dlg_blank_{run_id}_{item_id}"
            answer_widget_key = f"dlg_answer_{run_id}_{item_id}"

            if st.session_state.get(blank_widget_key):
                ack_blank[item_id] = True
                continue

            answer_value = st.session_state.get(answer_widget_key)

            if item["question_type"] == "MCQ":
                if not answer_value:
                    incomplete = True
                    continue

                manual_keys[item_id] = answer_value.split(".", 1)[0].strip()
                ack_blank.pop(item_id, None)
            else:
                answer_value = str(answer_value or "").strip()

                if not answer_value:
                    incomplete = True
                    continue

                manual_keys[item_id] = answer_value
                ack_blank.pop(item_id, None)

        st.session_state.ext_manual_keys = manual_keys
        st.session_state.ext_ack_blank = ack_blank

        if incomplete:
            st.warning(
                "Choose an answer, or check 'Leave blank', for every "
                "question above before continuing."
            )
        else:
            st.rerun()


def render_extraction_mode():
    """
    The "Extract existing questions" flow: upload a pre-existing
    question paper (PDF or image) and transcribe whatever is already
    printed on it into the same formatted Word document the
    generation flow produces — nothing is invented. A PDF page with a
    real text layer is sent to the model as plain text (cheap, fast,
    works with any text-capable model); only a page with no usable
    extractable text (a scanned page) — or a raw image upload — is
    rendered/sent as an image, which needs a vision-capable model.
    """

    st.session_state.setdefault("ext_run_id", 0)
    st.session_state.setdefault("ext_extracted", None)
    st.session_state.setdefault("ext_manual_keys", {})
    st.session_state.setdefault("ext_ack_blank", {})

    run_id = st.session_state.ext_run_id

    with st.sidebar:
        st.header("🔎 Extraction method")
        ext_method_label = st.radio(
            "How should questions be read from the file?",
            list(EXTRACTION_METHODS),
            key="ext_method",
            help=(
                "Built-in OCR reads PDFs and images on this server — no "
                "AI model or API key needed, nothing sent anywhere. "
                "Questions, options (1/2/3/4, a/b/c/d, A/B/C/D) and "
                "answers ('Ans: (b)', answer-key tables) are detected "
                "automatically; you can correct anything in the review "
                "step. Use the AI method for unusual layouts or "
                "handwriting — it needs a vision-capable model."
            ),
        )
        ext_method = EXTRACTION_METHODS[ext_method_label]

        ext_provider = PROVIDERS[0]
        ext_api_key = ""
        ext_base_url = None
        ext_model_id = ""

        if ext_method == "ai":
            st.divider()
            st.header("⚙️ AI Provider")

            ext_provider = st.radio(
                "Choose one provider for this run",
                PROVIDERS,
                key="ext_provider_radio",
                help=(
                    "Used to read the page images and transcribe the "
                    "questions on them — pick a model that supports "
                    "image input."
                ),
            )

            ext_api_key = ""
            ext_base_url = None
            ext_model_id = ""

            if ext_provider == "OmniRoute":
                st.caption(
                    "Self-hosted OpenAI-compatible proxy — must be "
                    "running before you extract."
                )

                omniroute_key = st.text_input(
                    "OmniRoute API key",
                    type="password",
                    key="ext_omniroute_api_key_input",
                    help=(
                        "Create this in OmniRoute Dashboard → "
                        "API Manager/Endpoints."
                    ),
                )

                omniroute_model_id = st.text_input(
                    "Model ID",
                    value="auto",
                    key="ext_omniroute_model_input",
                    help="Must be a vision-capable model.",
                )

                ext_api_key = omniroute_key.strip()
                ext_base_url = OMNIROUTE_BASE_URL
                ext_model_id = omniroute_model_id.strip()

            elif ext_provider == "Agent Router":
                agentrouter_key = st.text_input(
                    "Agent Router API key",
                    type="password",
                    key="ext_agentrouter_api_key_input",
                    help=(
                        "Get this from "
                        "https://agentrouter.org/console/token after "
                        "signing up at https://agentrouter.org/register."
                    ),
                )

                st.text_input(
                    "Agent Router base URL",
                    value=AGENTROUTER_BASE_URL,
                    disabled=True,
                    key="ext_agentrouter_base_url_display",
                )

                agentrouter_key_stripped = agentrouter_key.strip()

                agentrouter_model_id = render_model_dropdown_ui(
                    "ext_agentrouter",
                    fetch_agentrouter_models,
                    agentrouter_key_stripped,
                    "Agent Router",
                )

                ext_api_key = agentrouter_key_stripped
                ext_base_url = AGENTROUTER_BASE_URL
                ext_model_id = agentrouter_model_id.strip()

            else:  # Claude API
                claude_key = st.text_input(
                    "Claude API key",
                    type="password",
                    key="ext_claude_api_key_input",
                    help=f"Get this from {CLAUDE_API_DOCS_URL}",
                )

                claude_key_stripped = claude_key.strip()

                if anthropic is None:
                    st.error(
                        "The 'anthropic' package isn't installed — run "
                        "`pip install anthropic` and restart the app."
                    )

                claude_model_id = render_model_dropdown_ui(
                    "ext_claude",
                    fetch_claude_models,
                    claude_key_stripped,
                    "Claude API",
                )

                ext_api_key = claude_key_stripped
                ext_base_url = None
                ext_model_id = claude_model_id.strip()

            st.caption(
                "ℹ️ Pages with a real text layer are sent as plain text "
                "(any model works). Only scanned pages with no "
                "extractable text — or raw image uploads — are sent as "
                "an image, which needs a vision-capable model."
            )

        st.divider()
        st.header("🎯 Document settings")

        ext_subject = st.selectbox(
            "Subject", SUBJECTS, index=SUBJECTS.index("Biology"), key="ext_subject"
        )
        ext_grade = st.text_input("Grade", value="11", key="ext_grade")
        ext_topic = st.text_input(
            "Global topic",
            value="",
            key=f"ext_topic_input_{run_id}",
        )
        ext_difficulty = st.selectbox(
            "Difficulty (applied to every extracted question)",
            PLAIN_DIFFICULTIES,
            index=1,
            key="ext_difficulty",
        )
        ext_bloom_level = st.selectbox(
            "Bloom's level (applied to every extracted question)",
            BLOOM_LEVELS,
            index=1,
            key="ext_bloom_level",
        )

    ext_provider_ready = ext_method == "ocr" or (
        bool(ext_api_key)
        and bool(ext_model_id)
        and (ext_provider != "OmniRoute" or bool(ext_base_url))
    )

    uploaded_files = st.file_uploader(
        "Upload the question paper — a PDF, or one or more page "
        f"images (maximum {MAX_PDF_PAGES} pages/images)",
        type=EXTRACT_IMAGE_TYPES,
        accept_multiple_files=True,
        key=f"ext_uploader_{run_id}",
        help=(
            "Every question on every page is transcribed exactly as "
            "printed — nothing is invented. If a solution isn't "
            "visible on the page, you'll be prompted for it before "
            "the document can be created."
        ),
    )

    if not uploaded_files:
        st.info(
            "Upload a PDF or image(s) of the question paper to "
            "extract."
        )
        return

    pages_to_process = []
    source_names = []

    for uploaded_file in uploaded_files:
        source_names.append(uploaded_file.name)
        file_bytes = uploaded_file.getvalue()
        is_pdf = (
            uploaded_file.type == "application/pdf"
            or uploaded_file.name.lower().endswith(".pdf")
        )

        if is_pdf:
            # Prefer the PDF's real text layer — cheaper, faster, and
            # far more reliable than a vision call (works with any
            # text-capable model, not just vision-capable ones, and
            # isn't fighting image quality/OCR issues). Only pages
            # with too little extractable text (a scanned page with
            # no text layer at all) fall back to a rendered image.
            with st.spinner(f"Reading {uploaded_file.name}..."):
                text_pages = extract_pdf_pages(file_bytes)

            pages_needing_image = [
                page["page_number"]
                for page in text_pages
                if len(page["text"].strip()) < MIN_EXTRACT_TEXT_CHARS
            ]

            previews = {}

            if pages_needing_image:
                if fitz is None:
                    st.warning(
                        f"{uploaded_file.name}: "
                        f"{len(pages_needing_image)} page(s) have no "
                        "usable extractable text, and PyMuPDF isn't "
                        "installed to render them as images — those "
                        "page(s) will be skipped."
                    )
                else:
                    with st.spinner(
                        f"Rendering scanned page(s) from "
                        f"{uploaded_file.name}..."
                    ):
                        previews = render_all_pdf_page_previews(
                            file_bytes, zoom=2.5
                        )

            for page in text_pages:
                page_number = page["page_number"]
                label = f"{uploaded_file.name}, page {page_number}"

                if page_number not in pages_needing_image:
                    pages_to_process.append(
                        {
                            "label": label,
                            "mode": "text",
                            "page_text": page["text"],
                            "pdf_bytes": file_bytes,
                            "page_number": page_number,
                        }
                    )
                    continue

                png_bytes = previews.get(page_number)

                if png_bytes is None:
                    continue

                pages_to_process.append(
                    {
                        "label": label,
                        "mode": "image",
                        "image_bytes": png_bytes,
                        "image_mime": "image/png",
                    }
                )
        else:
            image_bytes, image_mime = prepare_image_for_vision(
                file_bytes, uploaded_file.type or "image/jpeg"
            )
            pages_to_process.append(
                {
                    "label": uploaded_file.name,
                    "mode": "image",
                    "image_bytes": image_bytes,
                    "image_mime": image_mime,
                }
            )

    if len(pages_to_process) > MAX_PDF_PAGES:
        st.error(
            f"The maximum supported document size is {MAX_PDF_PAGES} "
            f"pages/images. This upload has "
            f"{len(pages_to_process)}."
        )
        return

    if not pages_to_process:
        st.warning("No readable pages/images were found in this upload.")
        return

    source_name = (
        source_names[0]
        if len(source_names) == 1
        else f"{len(source_names)}_files"
    )

    st.subheader("📄 Pages to extract")

    for index, page in enumerate(pages_to_process):
        cols = st.columns([3, 2])

        with cols[0]:
            if page["mode"] == "text":
                st.caption(f"{page['label']} — extracted text")
                st.text_area(
                    "Extracted text preview (read-only)",
                    value=page["page_text"],
                    height=150,
                    disabled=True,
                    key=f"ext_textpreview_{run_id}_{index}",
                    label_visibility="collapsed",
                )
            else:
                st.image(
                    page["image_bytes"],
                    caption=(
                        f"{page['label']} (image — read with built-in OCR)"
                        if ext_method == "ocr"
                        else f"{page['label']} (image — sent to the AI model)"
                    ),
                    width="stretch",
                )

        with cols[1]:
            page["subtopic"] = st.text_input(
                "Sub-topic for this page",
                key=f"ext_subtopic_{run_id}_{index}",
            ).strip()

    subtopics_ready = all(
        page["subtopic"] for page in pages_to_process
    )

    if not subtopics_ready:
        st.warning("Enter a sub-topic for every page before extracting.")

    if not ext_provider_ready:
        st.info(
            f"Enter a valid {ext_provider} API key and model ID in "
            "the sidebar."
        )

    extract_clicked = st.button(
        "🔎 Extract questions from source",
        type="primary",
        width="stretch",
        disabled=not (ext_provider_ready and subtopics_ready),
    )

    if extract_clicked:
        ext_client = None

        if ext_method == "ai":
            try:
                ext_client = build_client(
                    ext_provider,
                    ext_api_key,
                    ext_base_url,
                    timeout_seconds=EXTRACTION_TIMEOUT_SECONDS,
                )
            except Exception as error:
                st.error(f"Couldn't set up the {ext_provider} client: {error}")
                return

        extracted_pages = []
        failed_pages = []
        progress = st.progress(0.0, text="Starting extraction...")

        for index, page in enumerate(pages_to_process):
            if ext_method == "ocr":
                progress.progress(
                    index / len(pages_to_process),
                    text=(
                        f"Reading {page['label']} "
                        f"({index + 1} of {len(pages_to_process)}) with "
                        "built-in OCR..."
                    ),
                )
                raw_questions, page_text, read_error = read_questions_without_ai(page)

                if read_error:
                    failed_pages.append(page["label"])
                    st.error(f"Couldn't read {page['label']}: {read_error}")

                    if "isn't installed" in read_error:
                        break

                    continue

                if not raw_questions:
                    failed_pages.append(page["label"])
                    st.warning(
                        f"No numbered questions were recognised on "
                        f"{page['label']}. The text that was read is "
                        "shown below — if it looks right, the layout "
                        "is unusual (try the AI method); if it looks "
                        "garbled, try a sharper image."
                    )

                    with st.expander(f"Text read from {page['label']}"):
                        st.text(page_text or "(no text found)")

                    continue

                cleaned_questions = []

                for raw_question in raw_questions:
                    cleaned, _ = normalize_extracted_question(
                        raw_question, ext_difficulty, ext_bloom_level
                    )

                    if cleaned is not None:
                        cleaned_questions.append(cleaned)

                extracted_pages.append(
                    {
                        "label": page["label"],
                        "subtopic": page["subtopic"],
                        "questions": cleaned_questions,
                    }
                )
                continue

            progress.progress(
                index / len(pages_to_process),
                text=(
                    f"Extracting {page['label']} "
                    f"({index + 1} of {len(pages_to_process)}) — waiting "
                    f"for the AI's reply (at most about "
                    f"{EXTRACTION_TIMEOUT_SECONDS * (MAX_TIMEOUT_RETRIES + 1) // 60 + 1} minutes)..."
                ),
            )

            sent_image = page.get("image_bytes") is not None

            try:
                raw_questions = extract_questions_from_page(
                    ext_provider,
                    ext_client,
                    ext_model_id.strip(),
                    page["label"],
                    image_png_bytes=page.get("image_bytes"),
                    image_mime=page.get("image_mime", "image/png"),
                    page_text=page.get("page_text"),
                )
            except HTMLResponseError as error:
                st.error(f"Extraction stopped: {error}")
                break
            except Exception as error:
                explanation = explain_provider_error(error, sent_images=sent_image)
                failed_pages.append(page["label"])
                st.error(f"Extraction failed on {page['label']}: {explanation}")

                # A timeout or a model that can't read images would fail
                # identically on every remaining page — stop now
                # instead of making the user wait through each of them.
                if isinstance(error, ProviderTimeoutError) or explanation.startswith(
                    "The selected model can't read images"
                ):
                    break

                continue

            cleaned_questions = []

            for raw_question in raw_questions:
                cleaned, _ = normalize_extracted_question(
                    raw_question, ext_difficulty, ext_bloom_level
                )

                if cleaned is not None:
                    cleaned_questions.append(cleaned)

            extracted_pages.append(
                {
                    "label": page["label"],
                    "subtopic": page["subtopic"],
                    "questions": cleaned_questions,
                }
            )

            if index < len(pages_to_process) - 1:
                time.sleep(MIN_REQUEST_DELAY)

        progress.progress(1.0, text="Extraction finished.")

        total_extracted = sum(
            len(page["questions"]) for page in extracted_pages
        )

        if total_extracted == 0:
            if not failed_pages:
                st.error(
                    "The AI replied but found no questions in the "
                    "uploaded file(s). Check the images are clear and "
                    "contain questions, then try again."
                )
            return

        if failed_pages or len(extracted_pages) < len(pages_to_process):
            st.warning(
                f"Extracted {len(extracted_pages)} of "
                f"{len(pages_to_process)} page(s); the rest can be "
                "re-tried by extracting again."
            )

        st.session_state.ext_extracted = extracted_pages
        st.session_state.ext_source_name = source_name
        st.session_state.ext_manual_keys = {}
        st.session_state.ext_ack_blank = {}
        st.session_state.pop("ext_pending_build", None)
        st.rerun()

    if not st.session_state.ext_extracted:
        return

    st.divider()
    st.subheader("✏️ Review & edit extracted questions")
    st.caption(
        "Everything below is editable — fix any transcription "
        "mistakes before creating the document. A question flagged "
        "'missing answer key' needs an answer before the document "
        "can be created."
    )

    extracted_pages = st.session_state.ext_extracted
    manual_keys = st.session_state.ext_manual_keys
    ack_blank = st.session_state.ext_ack_blank

    final_pages = []
    missing_items = []

    for page_index, page in enumerate(extracted_pages):
        with st.expander(
            f"{page['label']} — {len(page['questions'])} question(s)",
            expanded=False,
        ):
            final_questions = []

            for q_index, question in enumerate(page["questions"]):
                item_id = f"{page_index}_{q_index}"

                st.markdown(f"**Question {q_index + 1}**")

                question_text = st.text_area(
                    "Question",
                    value=question["question"],
                    key=f"ext_qtext_{run_id}_{item_id}",
                )

                override = manual_keys.get(item_id)
                default_key_value = (
                    override if override is not None else question["key"]
                )
                widget_suffix = override if override is not None else "auto"

                if question["question_type"] == "MCQ":
                    option_values = []
                    opt_cols = st.columns(4)

                    for opt_index in range(4):
                        with opt_cols[opt_index]:
                            option_values.append(
                                st.text_input(
                                    f"Option {opt_index + 1}",
                                    value=question["options"][opt_index],
                                    key=(
                                        f"ext_opt{opt_index}_{run_id}_"
                                        f"{item_id}"
                                    ),
                                )
                            )

                    key_options = ["— missing —", "1", "2", "3", "4"]
                    key_index = (
                        key_options.index(default_key_value)
                        if default_key_value in key_options
                        else 0
                    )
                    selected_key = st.selectbox(
                        "Correct option",
                        key_options,
                        index=key_index,
                        key=f"ext_key_{run_id}_{item_id}_{widget_suffix}",
                    )
                    resolved_key = (
                        "" if selected_key == "— missing —" else selected_key
                    )
                else:
                    option_values = []
                    resolved_key = st.text_input(
                        "Correct (numerical) answer — leave blank if "
                        "missing",
                        value=default_key_value,
                        key=f"ext_key_{run_id}_{item_id}_{widget_suffix}",
                    ).strip()

                explanation_text = st.text_area(
                    "Explanation (optional)",
                    value=question["explanation"],
                    key=f"ext_expl_{run_id}_{item_id}",
                )

                review_flags = [
                    flag
                    for flag in question["review_flags"]
                    if "MISSING ANSWER KEY" not in flag
                ]

                if not resolved_key:
                    if ack_blank.get(item_id):
                        review_flags.append(
                            "Answer intentionally left blank by the "
                            "reviewer — verify before use."
                        )
                    else:
                        review_flags.append(
                            "MISSING ANSWER KEY — the source did not "
                            "show a visible answer for this question. "
                            "Fill in the correct answer before use."
                        )
                        st.warning(
                            "⚠️ No answer key set for this question yet."
                        )
                        missing_items.append(
                            {
                                "item_id": item_id,
                                "label": page["label"],
                                "question": question_text,
                                "options": option_values,
                                "question_type": question["question_type"],
                            }
                        )

                final_questions.append(
                    {
                        "question_type": question["question_type"],
                        "question": question_text,
                        "options": option_values,
                        "key": resolved_key,
                        "difficulty": ext_difficulty,
                        "bloom_level": ext_bloom_level,
                        "explanation": explanation_text,
                        "review_flags": review_flags,
                    }
                )

                st.markdown("---")

            final_pages.append(
                {
                    "label": page["label"],
                    "subtopic": page["subtopic"],
                    "questions": final_questions,
                }
            )

    subject_ready = bool(ext_subject)
    topic_ready = bool(ext_topic.strip())
    subtopics_ready_final = all(
        page["subtopic"] for page in final_pages
    )

    if not topic_ready:
        st.info("Enter a global topic in the sidebar.")

    if not subtopics_ready_final:
        st.warning("Enter a sub-topic for every page.")

    create_clicked = st.button(
        "🚀 Create DOCX from extracted questions",
        type="primary",
        width="stretch",
        disabled=not (
            subject_ready and topic_ready and subtopics_ready_final
        ),
    )

    if create_clicked:
        st.session_state["ext_pending_build"] = True

    if st.session_state.get("ext_pending_build"):
        if missing_items:
            show_missing_keys_dialog(missing_items, run_id)
        else:
            _finish_extraction_docx(
                final_pages,
                ext_grade,
                ext_subject,
                ext_topic.strip(),
                st.session_state.get("ext_source_name", source_name),
            )


